/* FLUENTE — hand-authored content banks (loaded before the app script).
   LESSON_BANK: one entry per CURRICULUM unit, in exactly the JSON shape openLesson() renders —
   concept{title,bullets,examples,bridge} · mnemonic · note · drills[10]{q,options[4],answer,why,err} · speak · newcards.
   Every drill's `err` is an ERR_TAX key: a miss lands in the gap map, so Ripara is fed by the main path.
   Edit freely — node smoke.js validates shape, answer ranges and err keys. */
const LESSON_BANK = {
/* ===================== A1 ===================== */
a1u1:{concept:{title:"Italian is spelled the way it sounds — once you know 5 rules",
 bullets:["Every letter is pronounced, every time — no silent letters, no surprises.","C and G are hard before A/O/U (casa, gatto) and soft before E/I (cena, gelato). To keep them hard before E/I, Italian slips in an H: che, chi, ghe, ghi.","GLI is one sound (like the LLI in 'million'); GN is one sound (like the NY in 'canyon'); SC before E/I is 'sh'.","Double consonants are HELD — pala (shovel) vs palla (ball). Stretch them like you're savouring them."],
 examples:[{it:"Chi cerca, trova.",en:"Who seeks, finds. — CHI = 'kee', CE = 'che'"},{it:"Gli gnocchi sono squisiti.",en:"The gnocchi are exquisite. — GLI, GN, and a held CCH"}],
 bridge:[{en:"You already hold a double consonant in 'bookkeeper' — that k-k pause",it:"That pause is the whole difference between pala and palla"},{en:"The 'ny' in 'canyon'",it:"That's Italian GN: bagno, ogni, gnocchi"}]},
 mnemonic:"CHE CHI GHE GHI — the H is a helmet that keeps C and G hard.",
 note:"Say every letter · C/G soft only before E/I (an H makes them hard again) · doubles are held, not doubled",
 drills:[
  {q:"How do you pronounce the C in «cena» (dinner)?",options:["like CH in 'chess'","like K","like S","like SH"],answer:0,why:"C before E is soft — 'CHEH-na'",err:"ortografia"},
  {q:"«Chiesa» (church) starts with…",options:["a K sound: KYEH-za","a CH sound: CHEE-eh-za","an SH sound","a silent C"],answer:0,why:"CH before I = hard K",err:"ortografia"},
  {q:"«Gli» in «gli studenti» sounds most like…",options:["the LLI in 'million'","G + L + I, all separate","a hard G as in 'glee'","J as in 'jeep'"],answer:0,why:"GLI is one gliding sound",err:"ortografia"},
  {q:"Which word means 'ball'?",options:["palla","pala","pella","pola"],answer:0,why:"Held LL — pala is a shovel",err:"ortografia"},
  {q:"«Bagno» (bathroom): the GN is like…",options:["NY in 'canyon'","G + N as in 'ignore'","a silent G","NG in 'sing'"],answer:0,why:"GN = one 'ny' sound",err:"ortografia"},
  {q:"«Pesce» (fish) — the SC sounds like…",options:["SH","SK","S","CH"],answer:0,why:"SC before E/I = 'sh'",err:"ortografia"},
  {q:"«Spaghetti» keeps a hard G because of the…",options:["H after the G","double T","final I","letter P"],answer:0,why:"GH before E/I stays hard",err:"ortografia"},
  {q:"Which spelling means 'year' (not a rude word)?",options:["anno","ano","annno","ano'"],answer:0,why:"Held NN — the double matters here",err:"ortografia"},
  {q:"«Giorno» (day) starts with a sound like…",options:["J in 'job'","G in 'go'","Y in 'yes'","H"],answer:0,why:"G before I is soft",err:"ortografia"},
  {q:"Where is the stress in «medicina»?",options:["medi-CI-na","ME-dicina","medici-NA","me-DI-cina"],answer:0,why:"Most words stress the second-to-last syllable",err:"ortografia"}],
 speak:{prompt:"Say a sentence with GLI, GN and a held double: 'Gli gnocchi della nonna sono buonissimi.'",model:"Gli gnocchi della nonna sono buonissimi."},
 newcards:[{it:"gli gnocchi",en:"gnocchi (dumplings)",mn:"GLI + GN in one word — the pronunciation boss level",ex:"Gli gnocchi sono pronti."},{it:"la chiesa",en:"church",mn:"CHI = 'kee' — KEY-eh-za, the key to the church",ex:"La chiesa è in piazza."},{it:"anno / ano",en:"year / (rude!) — hold the NN",mn:"Hold the double or you insult someone at New Year",ex:"Buon anno!"}]},

a1u2:{concept:{title:"essere & avere — the two verbs you can't say a sentence without",
 bullets:["ESSERE = to be: sono, sei, è, siamo, siete, sono. Identity, origin, description.","AVERE = to have: ho, hai, ha, abbiamo, avete, hanno. Possession — and AGE, HUNGER, COLD: 'ho 25 anni', 'ho fame'.","Italian usually DROPS the subject pronoun: 'Sono studentessa', not 'Io sono' — the ending already says who.","'Mi chiamo…' literally = 'I call myself…' — that's how you give your name."],
 examples:[{it:"Ciao, mi chiamo Sara. Sono di Milano e ho ventitré anni.",en:"Hi, my name's Sara. I'm from Milan and I'm 23 (I HAVE 23 years)."},{it:"Siete studenti? — Sì, siamo studenti di medicina.",en:"Are you (all) students? — Yes, we're medical students."}],
 bridge:[{en:"I'm a student — no article in Italian either",it:"Sono studente"},{en:"'I have twenty years on me' — that's how Italian says age",it:"Ho vent'anni"}]},
 mnemonic:"Age, hunger, thirst, heat, cold, fear: you HAVE them in Italian. Ho fame — I HAVE hunger.",
 note:"essere = be (sono/sei/è) · avere = have (ho/hai/ha) · age & hunger take AVERE · drop 'io'",
 drills:[
  {q:"Io ___ studentessa di medicina.",options:["sono","sei","ho","è"],answer:0,why:"I am → sono",err:"coniugazione"},
  {q:"Marco ___ ventidue anni.",options:["ha","è","hai","sono"],answer:0,why:"Age takes avere — he HAS 22 years",err:"vocab"},
  {q:"Noi ___ di Bologna.",options:["siamo","abbiamo","siete","sono"],answer:0,why:"We are → siamo",err:"coniugazione"},
  {q:"«Ho fame» means…",options:["I'm hungry","I have a family","I'm famous","I'm fine"],answer:0,why:"Hunger is something you HAVE",err:"vocab"},
  {q:"Tu ___ italiano?",options:["sei","è","hai","siamo"],answer:0,why:"You are → sei",err:"coniugazione"},
  {q:"Loro ___ due figli.",options:["hanno","sono","hai","avete"],answer:0,why:"They have → hanno",err:"coniugazione"},
  {q:"Which is the most natural way to say 'I am tired'?",options:["Sono stanca.","Io sono stanca io.","Ho stanca.","Sono stanchezza."],answer:0,why:"Drop the pronoun; tired = a state, so essere",err:"ordine_parole"},
  {q:"«Come ___ chiami?» — «Mi chiamo Luca.»",options:["ti","mi","si","ci"],answer:0,why:"You call YOURSELF → ti chiami",err:"pronomi"},
  {q:"Voi ___ freddo?",options:["avete","siete","hanno","è"],answer:0,why:"Cold is something you HAVE",err:"vocab"},
  {q:"Lei ___ medico.",options:["è","ha","sei","sono"],answer:0,why:"She is → è (with the accent)",err:"ortografia"}],
 speak:{prompt:"Introduce yourself: name, where you're from, your age, what you study.",model:"Mi chiamo Anna, sono di Londra, ho ventiquattro anni e studio medicina."},
 newcards:[{it:"Ho fame / ho sete",en:"I'm hungry / I'm thirsty",mn:"You HAVE hunger like you have a backpack",ex:"Ho fame, andiamo a mangiare?"},{it:"Mi chiamo…",en:"My name is… (I call myself)",mn:"I call MYSELF — mi",ex:"Mi chiamo Sara, piacere."},{it:"Piacere!",en:"Nice to meet you!",mn:"Pleasure! — say it with the handshake",ex:"Piacere, sono Marco."}]},

a1u3:{concept:{title:"At the bar — order like you belong there",
 bullets:["'Vorrei' (I would like) is the magic word: polite, never wrong. 'Vorrei un caffè, per favore.'","Un caffè = an espresso. Cappuccino is a MORNING drink; after 11 it marks you as a tourist.","Numbers 1–20 unlock prices: uno, due, tre, quattro, cinque, sei, sette, otto, nove, dieci… venti.","'Quanto costa?' (how much?) · 'Il conto, per favore' (the bill) · 'Scontrino' = the receipt they legally must give you."],
 examples:[{it:"Buongiorno! Vorrei un cappuccino e un cornetto, per favore.",en:"Good morning! I'd like a cappuccino and a croissant, please."},{it:"Quant'è? — Due e cinquanta.",en:"How much is it? — Two fifty."}],
 bridge:[{en:"'I'd like a coffee' — same politeness move",it:"Vorrei un caffè"},{en:"'How much is it?'",it:"Quant'è? (literally 'how much is?')"}]},
 mnemonic:"VORREI = your VIP pass: say it and any bar in Italy opens.",
 note:"Vorrei + thing + per favore · un caffè = espresso · cappuccino only in the morning · Quant'è? · Il conto",
 drills:[
  {q:"The polite way to order: «___ un caffè, per favore.»",options:["Vorrei","Voglio","Ho","Sono"],answer:0,why:"Vorrei = I'd like — soft and polite",err:"registro"},
  {q:"«Un caffè» in Italy is…",options:["an espresso","a large filter coffee","a cappuccino","an iced coffee"],answer:0,why:"Caffè = espresso by default",err:"vocab"},
  {q:"«Quanto costa?» means…",options:["How much is it?","What is it?","Where is it?","Is it good?"],answer:0,why:"quanto = how much",err:"vocab"},
  {q:"Which number is «diciassette»?",options:["17","7","70","27"],answer:0,why:"dieci + sette",err:"vocab"},
  {q:"«Il conto, per favore» — you are asking for…",options:["the bill","the count","the menu","the coffee"],answer:0,why:"conto = bill/account",err:"vocab"},
  {q:"Ordering a cappuccino at 4 pm is…",options:["fine, but marks you as a tourist","illegal","only possible with a cornetto","free"],answer:0,why:"Milk after lunch is un-Italian",err:"vocab"},
  {q:"«Vorrei ___ acqua naturale.»",options:["un'","un","una","uno"],answer:0,why:"Feminine noun starting with a vowel → un'",err:"articoli"},
  {q:"«Tre euro e venti» is…",options:["€3.20","€3.02","€20.03","€32"],answer:0,why:"euro e cents",err:"vocab"},
  {q:"A «cornetto» is…",options:["a croissant","an ice cream cone","a horn","a small corner"],answer:0,why:"The breakfast pastry",err:"vocab"},
  {q:"Two coffees: «___ caffè, per favore.»",options:["Due","Dui","Doi","Deu"],answer:0,why:"due = two",err:"ortografia"}],
 speak:{prompt:"Order a coffee and a croissant politely, then ask how much it is.",model:"Vorrei un caffè e un cornetto, per favore. Quant'è?"},
 newcards:[{it:"Vorrei…",en:"I would like…",mn:"VIP pass to every counter in Italy",ex:"Vorrei un cappuccino, per favore."},{it:"Quant'è?",en:"How much is it?",mn:"How-much-is? — three words squeezed into two",ex:"Quant'è? — Un euro e dieci."},{it:"lo scontrino",en:"the receipt",mn:"They must SCONtrino you the receipt by law",ex:"Ecco lo scontrino."}]},

a1u4:{concept:{title:"Family words & the -ARE verbs that carry everyday life",
 bullets:["-ARE verbs are the big family: parlare → parlo, parli, parla, parliamo, parlate, parlano. Learn one, own hundreds.","'My' changes with the noun: mio fratello / mia sorella / i miei genitori — the possessive agrees like an adjective.","THE RULE that trips everyone: with ONE family member you DROP the article — 'mia madre', not 'la mia madre'. Plural gets it back: 'i miei fratelli'.","Family vocabulary: madre/padre, fratello/sorella, nonno/nonna, zio/zia, cugino/cugina, figlio/figlia."],
 examples:[{it:"Mia sorella lavora in ospedale e i miei genitori abitano a Torino.",en:"My sister works in a hospital and my parents live in Turin."},{it:"Parliamo italiano a casa.",en:"We speak Italian at home."}],
 bridge:[{en:"'I speak, you speak, we speak' — English changes only for 'he speaks'; Italian changes every time",it:"parlo, parli, parla, parliamo, parlate, parlano"},{en:"'my mother' (no 'the')",it:"mia madre — Italian also drops 'the' for one relative"}]},
 mnemonic:"One relative = no article. Mia madre is unique — she needs no 'the'. Cousins come in crowds: i miei cugini.",
 note:"-are → -o -i -a -iamo -ate -ano · mio/mia agrees · ONE relative = drop 'the' (mia madre, i miei fratelli)",
 drills:[
  {q:"___ madre è medico.",options:["Mia","La mia","Mio","La mio"],answer:0,why:"One relative: no article",err:"articoli"},
  {q:"___ fratelli studiano a Roma.",options:["I miei","Miei","Il mio","I mio"],answer:0,why:"Plural relatives get the article back",err:"articoli"},
  {q:"Noi ___ italiano ogni giorno.",options:["parliamo","parlano","parlate","parla"],answer:0,why:"we → -iamo",err:"coniugazione"},
  {q:"Loro ___ a Milano.",options:["abitano","abitiamo","abita","abiti"],answer:0,why:"they → -ano",err:"coniugazione"},
  {q:"«Mio cugino» is…",options:["my (male) cousin","my nephew","my uncle","my brother-in-law"],answer:0,why:"cugino = cousin",err:"vocab"},
  {q:"Tu ___ molto? (lavorare)",options:["lavori","lavora","lavoro","lavorate"],answer:0,why:"you → -i",err:"coniugazione"},
  {q:"___ nonna ha ottant'anni.",options:["Mia","Mio","La mia","Mie"],answer:0,why:"Feminine, single relative, no article",err:"concordanza"},
  {q:"Voi ___ inglese? (studiare)",options:["studiate","studiamo","studiano","studi"],answer:0,why:"you all → -ate",err:"coniugazione"},
  {q:"«I miei genitori» means…",options:["my parents","my relatives","my grandparents","my children"],answer:0,why:"genitori = parents (false friend: not 'geniuses')",err:"vocab"},
  {q:"Lei ___ in una farmacia.",options:["lavora","lavoro","lavori","lavorano"],answer:0,why:"she → -a",err:"coniugazione"}],
 speak:{prompt:"Say who's in your family and what two of them do.",model:"Mia madre è infermiera e mio padre lavora in banca. I miei fratelli studiano."},
 newcards:[{it:"i genitori",en:"parents",mn:"GENItori are not geniuses — just parents",ex:"I miei genitori vivono a Londra."},{it:"il nipote / la nipote",en:"nephew, niece — AND grandson, granddaughter",mn:"One word for both — context decides",ex:"Mia nonna ha sei nipoti."},{it:"abitare",en:"to live (somewhere)",mn:"You inHABIT a place — abito a Milano",ex:"Abito vicino all'ospedale."}]},

a1u5:{concept:{title:"Getting around — c'è / ci sono and the -ERE / -IRE verbs",
 bullets:["C'È = there is · CI SONO = there are. 'C'è una farmacia qui vicino?' 'Ci sono due fermate.'","Directions: a destra (right), a sinistra (left), dritto (straight), vicino/lontano (near/far), la fermata (stop), la metro.","-ERE verbs: prendere → prendo, prendi, prende, prendiamo, prendete, prendono. -IRE verbs: partire → parto, parti, parte, partiamo, partite, partono.","Some -IRE verbs add -ISC- in the singular and 'loro': capire → capisco, capisci, capisce, capiamo, capite, capiscono. Finire, preferire, pulire do the same."],
 examples:[{it:"Scusi, c'è una farmacia qui vicino? — Sì, prenda la prima a destra.",en:"Excuse me, is there a pharmacy nearby? — Yes, take the first on the right."},{it:"Non capisco: la metro parte da qui?",en:"I don't understand: does the metro leave from here?"}],
 bridge:[{en:"'There is / there are' — Italian points at the place with 'ci' (there)",it:"c'è / ci sono"},{en:"'I understand' — capisco, with the -isc- engine inside",it:"capisco, capisci, capisce"}]},
 mnemonic:"C'È for one, CI SONO for a crowd. And capISCo: the -ISC- is the fish (pesce) swimming in the middle of the verb.",
 note:"c'è = there is · ci sono = there are · -ere/-ire: -o -i -e -iamo -ete/-ite -ono · capire adds -isc-",
 drills:[
  {q:"___ una fermata della metro qui vicino?",options:["C'è","Ci sono","È","Sono"],answer:0,why:"One stop → c'è",err:"vocab"},
  {q:"___ molti turisti in Duomo.",options:["Ci sono","C'è","Sono","Ha"],answer:0,why:"Plural → ci sono",err:"concordanza"},
  {q:"Io non ___ (capire).",options:["capisco","capo","capio","capisce"],answer:0,why:"-isc- verb, io → capisco",err:"coniugazione"},
  {q:"Noi ___ il tram (prendere).",options:["prendiamo","prendono","prendete","prende"],answer:0,why:"we → -iamo",err:"coniugazione"},
  {q:"«A sinistra» means…",options:["on the left","on the right","straight ahead","behind"],answer:0,why:"sinistra = left",err:"vocab"},
  {q:"Loro ___ alle otto (partire).",options:["partono","partano","partiscono","partiamo"],answer:0,why:"partire has no -isc-; they → -ono",err:"coniugazione"},
  {q:"Tu ___ il caffè o il tè? (preferire)",options:["preferisci","preferi","preferisce","preferite"],answer:0,why:"-isc- verb, tu → -isci",err:"coniugazione"},
  {q:"«Vada dritto» means…",options:["go straight","turn right","go back","stop here"],answer:0,why:"dritto = straight",err:"vocab"},
  {q:"Voi ___ a che ora? (finire)",options:["finite","finiscete","finiamo","finiscono"],answer:0,why:"voi never takes -isc-",err:"coniugazione"},
  {q:"«È lontano?» — «No, è ___.»",options:["vicino","destra","dritto","fermata"],answer:0,why:"far? no, near",err:"vocab"}],
 speak:{prompt:"Ask if there's a pharmacy nearby and say you don't understand the answer.",model:"Scusi, c'è una farmacia qui vicino? Mi dispiace, non capisco."},
 newcards:[{it:"c'è / ci sono",en:"there is / there are",mn:"CI = there, È/SONO = is/are",ex:"C'è un bar all'angolo."},{it:"la fermata",en:"the (bus/metro) stop",mn:"Where the bus FERMA (stops)",ex:"La fermata è a cento metri."},{it:"capire (capisco)",en:"to understand",mn:"The -ISC- fish swims in the middle",ex:"Non capisco, può ripetere?"}]},

/* ===================== A2 ===================== */
a2u1:{concept:{title:"'I ate' and 'I have eaten' are ONE tense — the passato prossimo",
 bullets:["Build it: present of AVERE or ESSERE + past participle (-ato / -uto / -ito). Ho mangiato, ho avuto, ho dormito.","Most verbs take AVERE. ESSERE goes with movement & change (andare, venire, partire, nascere, morire, diventare) and every reflexive (mi sono svegliata).","With ESSERE the participle agrees like an adjective: Marco è andato, Maria è andata, loro sono andati.","Irregular participles you'll use daily: fatto, detto, visto, preso, messo, scritto, letto, aperto, stato, venuto."],
 examples:[{it:"Ieri ho lavorato dieci ore e sono tornata a casa alle nove.",en:"Yesterday I worked ten hours and came home at nine."},{it:"Hai visto il paziente? — Sì, l'ho visto stamattina.",en:"Did you see the patient? — Yes, I saw him this morning."}],
 bridge:[{en:"'I have eaten' — you already build a past with HAVE + participle",it:"Ho mangiato — and Italian uses it for 'I ate' too"},{en:"'She is gone' — old English used BE for movement",it:"È andata — Italian still does, and the -a agrees with her"}]},
 mnemonic:"Movement, change, mirror (reflexive) → ESSERE, and the participle dresses to match: andatO / andatA.",
 note:"ho/hai/ha + -ato/-uto/-ito · movement, change, reflexive → essere + agreement (è tornatA) · irregulars: fatto detto visto preso",
 drills:[
  {q:"Ieri ___ un film bellissimo.",options:["ho visto","sono visto","ho veduto","è visto"],answer:0,why:"vedere → avere + visto",err:"ausiliare"},
  {q:"Maria ___ a casa alle sette.",options:["è tornata","ha tornato","è tornato","ha tornata"],answer:0,why:"Movement → essere; Maria → -a",err:"ausiliare"},
  {q:"Noi ___ tutto il weekend.",options:["abbiamo studiato","siamo studiati","abbiamo studiati","siamo studiato"],answer:0,why:"studiare takes avere, no agreement",err:"ausiliare"},
  {q:"Stamattina mi ___ alle sei.",options:["sono svegliata","ho svegliato","sono svegliato","ho svegliata"],answer:0,why:"Reflexive → essere + agreement (a woman speaking)",err:"ausiliare"},
  {q:"Loro ___ in Italia nel 2020.",options:["sono arrivati","hanno arrivato","sono arrivato","hanno arrivati"],answer:0,why:"Arrival = movement → essere, plural -i",err:"ausiliare"},
  {q:"Che cosa ___ il medico? (dire)",options:["ha detto","ha dicuto","è detto","ha dito"],answer:0,why:"dire → detto, irregular",err:"coniugazione"},
  {q:"___ la finestra? (tu, aprire)",options:["Hai aperto","Sei aperto","Hai aprito","Hai aperta"],answer:0,why:"aprire → aperto, takes avere",err:"coniugazione"},
  {q:"Il paziente ___ ieri notte. (morire)",options:["è morto","ha morto","è morito","ha morito"],answer:0,why:"Change of state → essere; morire → morto",err:"ausiliare"},
  {q:"Ho ___ una lettera al primario. (scrivere)",options:["scritto","scrivuto","scritta","scrivato"],answer:0,why:"scrivere → scritto; no agreement with avere",err:"coniugazione"},
  {q:"«Sono stata a Roma» — the speaker is…",options:["a woman who has been to Rome","a man who was in Rome","someone still in Rome","a man who is going to Rome"],answer:0,why:"statA = feminine agreement with essere",err:"concordanza"}],
 speak:{prompt:"Say three things you did yesterday, one with essere.",model:"Ieri ho studiato, ho mangiato con un'amica e sono tornata a casa tardi."},
 newcards:[{it:"sono tornata / tornato",en:"I came back (f / m)",mn:"Movement → essere, and the ending wears your gender",ex:"Sono tornata a casa alle nove."},{it:"ho fatto",en:"I did / I made",mn:"fare → FATTO, the irregular everyone says 50 times a day",ex:"Ho fatto il turno di notte."},{it:"mi sono svegliato/a",en:"I woke up",mn:"Reflexives always ride with essere",ex:"Mi sono svegliata alle sei."}]},

a2u2:{concept:{title:"The imperfetto — the video camera of the past",
 bullets:["Passato prossimo is a PHOTO (one finished event). Imperfetto is a VIDEO (background, habit, ongoing).","Build it: drop -re, add -vo -vi -va -vamo -vate -vano: parlavo, avevo, dormivo. Only essere is irregular: ero, eri, era, eravamo, eravate, erano.","Use it for: 'used to' (da bambino giocavo), 'was …ing' (dormivo quando…), age/weather/feelings in the past (avevo dieci anni, pioveva, ero stanca).","Classic pair: imperfetto sets the scene, passato prossimo interrupts it — 'Dormivo quando ha squillato il telefono.'"],
 examples:[{it:"Da bambina abitavo a Napoli e andavo sempre al mare.",en:"As a child I lived in Naples and always went (used to go) to the seaside."},{it:"Faceva freddo, pioveva, e il pronto soccorso era pieno.",en:"It was cold, it was raining, and the ER was full."}],
 bridge:[{en:"'I used to play outside' — the 'used to' feeling",it:"Giocavo fuori"},{en:"'I was sleeping when you called' — the '-ing past'",it:"Dormivo quando hai chiamato"}]},
 mnemonic:"-AVO -EVO -IVO: the VIDEO tense. If you could film it running, it's imperfetto.",
 note:"'used to' + 'was doing' + past scenery/age/weather = imperfetto (-avo/-evo/-ivo) · essere: ero era erano",
 drills:[
  {q:"Da bambino ___ sempre al parco.",options:["andavo","sono andato","andrò","vado"],answer:0,why:"Habit in the past → imperfetto",err:"tempo_passati"},
  {q:"Ieri ___ freddo e pioveva.",options:["faceva","ha fatto","fa","farà"],answer:0,why:"Weather as background → imperfetto",err:"tempo_passati"},
  {q:"___ dieci anni quando siamo arrivati in Italia.",options:["Avevo","Ho avuto","Ero","Sono stato"],answer:0,why:"Age in the past → imperfetto of avere",err:"tempo_passati"},
  {q:"Noi ___ stanchi dopo il turno. (essere)",options:["eravamo","siamo stati","eravate","erano"],answer:0,why:"State/feeling → imperfetto; we → eravamo",err:"coniugazione"},
  {q:"Mentre ___, è arrivato il medico.",options:["dormivo","ho dormito","dormo","dormirò"],answer:0,why:"Ongoing action interrupted → imperfetto",err:"tempo_passati"},
  {q:"Ieri ___ un caffè al bar. (one time)",options:["ho preso","prendevo","prendo","prenderò"],answer:0,why:"One finished event → passato prossimo",err:"tempo_passati"},
  {q:"Loro ___ ogni estate in Sicilia. (andare)",options:["andavano","sono andati","andavamo","andarono"],answer:0,why:"Every summer = habit → imperfetto, they → -avano",err:"tempo_passati"},
  {q:"Il paziente ___ la febbre da tre giorni. (avere, past scene)",options:["aveva","ha avuto","ha","avrà"],answer:0,why:"Ongoing state in the past → imperfetto",err:"tempo_passati"},
  {q:"Tu ___ sempre in ritardo! (essere)",options:["eri","sei stato","era","eravate"],answer:0,why:"Habit → imperfetto; you → eri",err:"coniugazione"},
  {q:"Ho aspettato due ore. — Why passato prossimo, not imperfetto?",options:["The duration is bounded ('two hours')","Waiting is always passato prossimo","Because it's negative","Because it's in the first person"],answer:0,why:"Bounded duration = finished block = photo",err:"tempo_passati"}],
 speak:{prompt:"Describe your life five years ago: where you lived, what you did every day.",model:"Cinque anni fa abitavo a Londra, studiavo biologia e ogni sera uscivo con gli amici."},
 newcards:[{it:"da bambina / da bambino",en:"as a child",mn:"DA marks the era: 'from childhood' → imperfetto follows",ex:"Da bambina avevo paura del buio."},{it:"mentre",en:"while",mn:"MENTRE opens the video, the photo interrupts",ex:"Mentre studiavo, è squillato il telefono."},{it:"c'era / c'erano",en:"there was / there were",mn:"c'è in the video tense",ex:"C'erano tanti pazienti in sala d'attesa."}]},

a2u3:{concept:{title:"Dal medico — 'mi fa male' and the body",
 bullets:["Pain works like piacere: the body part is the SUBJECT. 'Mi fa male la testa' = the head hurts TO ME. Plural: 'Mi fanno male le gambe.'","Alternative: 'Ho mal di testa / di gola / di stomaco / di schiena' — HAVE + mal di + part.","Body parts with rebel plurals: il braccio → le braccia, il ginocchio → le ginocchia, la mano → le mani, il dito → le dita, l'orecchio → le orecchie.","Doctor's questions you'll ask: 'Dove le fa male?' 'Da quanto tempo?' 'Ha la febbre?' 'Prende farmaci?'"],
 examples:[{it:"Mi fa male la gola da due giorni e ho un po' di febbre.",en:"My throat has hurt for two days and I have a bit of a fever."},{it:"Dottore, mi fanno male le ginocchia quando salgo le scale.",en:"Doctor, my knees hurt when I climb the stairs."}],
 bridge:[{en:"'My head is killing me' — the head is the one doing something to you",it:"Mi fa male la testa — the head 'does hurt' to me"},{en:"'I have a headache'",it:"Ho mal di testa — same HAVE structure"}]},
 mnemonic:"MI FA MALE: the body part is the bully, you're the victim. Plural bullies → MI FANNO MALE.",
 note:"mi fa male + one part / mi fanno male + plural · ho mal di testa · braccio→braccia, mano→mani · Dove le fa male? Da quanto?",
 drills:[
  {q:"Mi ___ male le gambe.",options:["fanno","fa","fai","faccio"],answer:0,why:"Plural body part → fanno",err:"concordanza"},
  {q:"«Ho mal di gola» means…",options:["I have a sore throat","I have a bad goal","My mouth hurts","I feel sick"],answer:0,why:"gola = throat",err:"vocab"},
  {q:"The plural of «il braccio» is…",options:["le braccia","i bracci","le bracce","i braccia"],answer:0,why:"Rebel plural: le braccia",err:"concordanza"},
  {q:"Dottore, ___ fa male la schiena.",options:["mi","io","me","a"],answer:0,why:"To me → mi",err:"pronomi"},
  {q:"«Da quanto tempo ha questo dolore?» asks…",options:["how long they've had the pain","how strong the pain is","where the pain is","whether the pain moves"],answer:0,why:"da quanto tempo = since when / how long",err:"vocab"},
  {q:"Il paziente ha la febbre ___ tre giorni.",options:["da","per","fa","in"],answer:0,why:"Ongoing since → da + presente",err:"preposizioni"},
  {q:"«Le dita» are…",options:["fingers/toes","teeth","dates","diets"],answer:0,why:"il dito → le dita",err:"vocab"},
  {q:"Signora, dove ___ fa male?",options:["le","la","lei","ti"],answer:0,why:"Formal 'to you' → Le",err:"registro"},
  {q:"Mi fa male ___ testa.",options:["la","il","le","una"],answer:0,why:"Body parts take the definite article, not 'my'",err:"articoli"},
  {q:"«Prende farmaci?» — the doctor asks if you…",options:["take any medication","have a pharmacy","feel tired","need a prescription"],answer:0,why:"farmaci = medicines",err:"vocab"}],
 speak:{prompt:"You're the patient: say what hurts, since when, and whether you have a fever.",model:"Mi fa male lo stomaco da ieri sera e non ho la febbre."},
 newcards:[{it:"Mi fa male…",en:"… hurts (me)",mn:"The body part is the bully — it 'does bad' to me",ex:"Mi fa male la testa."},{it:"Da quanto tempo?",en:"Since when? / For how long?",mn:"DA = since — the doctor's first question",ex:"Da quanto tempo ha la tosse?"},{it:"la ricetta",en:"the prescription (also: recipe)",mn:"The doctor's RECIPE for you",ex:"Le faccio una ricetta per l'antibiotico."}]},

a2u4:{concept:{title:"Fare la spesa — 'some', quantities and food",
 bullets:["'Some' = DI + article: del pane, della pasta, dei pomodori, delle mele. Or 'un po' di' (a bit of) — never wrong.","Quantities skip the article: un chilo DI pomodori, un litro DI latte, un etto (100 g) DI prosciutto, una fetta DI torta.","At the market: 'Quanto costano le pesche?' 'Ne vorrei un chilo.' — NE = 'of them'. 'Altro?' (anything else?) 'Basta così, grazie.'","Fare la spesa = grocery shopping · fare spese = shopping for clothes. Different animals."],
 examples:[{it:"Vorrei del pane, un etto di prosciutto crudo e un po' di formaggio.",en:"I'd like some bread, 100 g of prosciutto and a bit of cheese."},{it:"Quanto costano le pesche? — Ne prendo un chilo.",en:"How much are the peaches? — I'll take a kilo (of them)."}],
 bridge:[{en:"'a kilo OF tomatoes' — same OF",it:"un chilo DI pomodori"},{en:"'some bread' — Italian says 'of the bread'",it:"del pane"}]},
 mnemonic:"DEL DELLA DEI DELLE = 'some'. Quantities are greedy: they eat the article — un chilo DI.",
 note:"some = di+article (del pane, delle mele) · quantities: un chilo DI · ne = of them · un etto = 100 g · fare la spesa = groceries",
 drills:[
  {q:"Vorrei ___ pane, per favore.",options:["del","di","dello","il"],answer:0,why:"some bread → del",err:"articoli"},
  {q:"Un chilo ___ mele.",options:["di","delle","de","dei"],answer:0,why:"Quantity + DI, no article",err:"preposizioni"},
  {q:"«Un etto» is…",options:["100 grams","1 kilo","a piece","a dozen"],answer:0,why:"etto = hectogram",err:"vocab"},
  {q:"Quanto costano le pesche? — ___ prendo due chili.",options:["Ne","Le","Li","Ci"],answer:0,why:"Of them → ne",err:"pronomi"},
  {q:"Vorrei ___ zucchero. (some)",options:["dello","del","della","degli"],answer:0,why:"lo zucchero → dello",err:"articoli"},
  {q:"«Fare la spesa» means…",options:["to do the grocery shopping","to spend money","to go clothes shopping","to cook"],answer:0,why:"la spesa = groceries",err:"vocab"},
  {q:"Una bottiglia ___ vino rosso.",options:["di","del","da","con"],answer:0,why:"Container + DI",err:"preposizioni"},
  {q:"«Altro?» at the counter means…",options:["Anything else?","Another one?","The other one?","Is that all?"],answer:0,why:"Altro? = anything else?",err:"vocab"},
  {q:"Ho comprato ___ uova. (some)",options:["delle","degli","dei","della"],answer:0,why:"le uova (fem. plural) → delle",err:"concordanza"},
  {q:"«Basta così, grazie» means…",options:["That's enough, thanks","Stop it, thanks","Too much, thanks","Just this, please"],answer:0,why:"basta così = that's all",err:"vocab"}],
 speak:{prompt:"Buy some bread, 200 g of cheese and a kilo of tomatoes; then say that's all.",model:"Vorrei del pane, due etti di formaggio e un chilo di pomodori. Basta così, grazie."},
 newcards:[{it:"un etto",en:"100 grams",mn:"h-ECTO-gram → etto",ex:"Due etti di prosciutto, per favore."},{it:"ne",en:"of it / of them",mn:"Ne = the 'of them' you always forget",ex:"Ne prendo tre."},{it:"fare la spesa",en:"to do the grocery shopping",mn:"la SPESA = the expense you can't avoid: food",ex:"Faccio la spesa il sabato."}]},

a2u5:{concept:{title:"Plans: the futuro semplice and the three helper verbs",
 bullets:["Futuro: infinitive minus final -e + -ò -ai -à -emo -ete -anno. -ARE verbs shift A→E: parlerò, mangerò. Essere: sarò · avere: avrò · andare: andrò · fare: farò.","Italian uses the PRESENT for planned near future: 'Domani parto' (tomorrow I'm leaving). The futuro is for real predictions, promises, and guesses.","The guessing future: 'Sarà stanco' = he's probably tired. 'Che ore saranno? Saranno le tre.' — English uses 'must be'.","DOVERE (must: devo), POTERE (can: posso), VOLERE (want: voglio) + infinitive: 'Devo studiare', 'Posso entrare?', 'Voglio diventare medico'."],
 examples:[{it:"L'anno prossimo farò il tirocinio in chirurgia e dovrò parlare solo italiano.",en:"Next year I'll do my clerkship in surgery and I'll have to speak only Italian."},{it:"Il primario non risponde: sarà in sala operatoria.",en:"The chief isn't answering: he must be in the operating theatre."}],
 bridge:[{en:"'He must be tired' — the guessing use",it:"Sarà stanco — future used as 'probably'"},{en:"'I'm leaving tomorrow' — present for a plan",it:"Domani parto — same trick"}]},
 mnemonic:"Futuro for PPG: Predictions, Promises, Guesses. Plans? The present does the job: domani parto.",
 note:"-ò -ai -à -emo -ete -anno (parlerò, sarò, avrò, andrò) · near plans → presente · 'sarà stanco' = must be tired · devo/posso/voglio + infinito",
 drills:[
  {q:"Domani ___ il tirocinio in reparto. (io, iniziare)",options:["inizierò","inizio","inizierà","inizia"],answer:0,why:"Prediction/plan in the future → -erò",err:"futuro"},
  {q:"Non risponde… ___ in sala operatoria.",options:["Sarà","È","Sarebbe","Era"],answer:0,why:"Guess → futuro ('must be')",err:"futuro"},
  {q:"Noi ___ in Sicilia ad agosto. (andare)",options:["andremo","anderemo","andiamo sempre","andavamo"],answer:0,why:"andare drops the vowel: andr-emo",err:"coniugazione"},
  {q:"___ studiare stasera, ho l'esame domani. (must)",options:["Devo","Posso","Voglio","Vorrei"],answer:0,why:"Obligation → dovere",err:"vocab"},
  {q:"___ entrare, dottore? (may I)",options:["Posso","Devo","Voglio","So"],answer:0,why:"Permission → potere",err:"vocab"},
  {q:"Loro ___ medici tra sei anni. (essere)",options:["saranno","seranno","sono","saranno stati"],answer:0,why:"essere → sar- + -anno",err:"coniugazione"},
  {q:"Tu ___ con noi? (venire)",options:["verrai","venirai","vieni","verresti"],answer:0,why:"venire → verr-",err:"coniugazione"},
  {q:"Che ore sono? — ___ le dieci, più o meno.",options:["Saranno","Sono","Erano","Sarebbero"],answer:0,why:"Guessing the time → futuro",err:"futuro"},
  {q:"Io ___ diventare pediatra.",options:["voglio","posso","devo","volo"],answer:0,why:"Want → volere (voglio)",err:"vocab"},
  {q:"Vi ___ i risultati domani. (mandare, we)",options:["manderemo","mandiamo","mandaremo","manderemmo"],answer:0,why:"-are → -er-: mander-emo (promise)",err:"coniugazione"}],
 speak:{prompt:"Say two things you'll do next year and one thing you must do this week.",model:"L'anno prossimo farò il tirocinio e andrò in Sicilia. Questa settimana devo studiare anatomia."},
 newcards:[{it:"sarà",en:"he/she/it will be — or 'probably is'",mn:"The future that guesses: sarà stanco = must be tired",ex:"Non risponde, sarà occupato."},{it:"dovere / potere / volere",en:"must / can / want",mn:"The three doormen before every infinitive",ex:"Devo andare, posso chiamarti dopo?"},{it:"tra / fra + time",en:"in (X time from now)",mn:"TRA sei anni = six years from now",ex:"Ci vediamo tra un'ora."}]},

/* ===================== B1 ===================== */
b1u1:{concept:{title:"Secondo me… — opinions and the mood of 'if I were you'",
 bullets:["After 'penso che / credo che / mi sembra che' Italian switches the verb into its 'if I WERE you' mood: 'Penso che lui ABBIA ragione' (not 'ha').","Congiuntivo presente is easy: io/tu/lui share ONE form (parli, abbia, sia, faccia), noi = -iamo, loro = -ino/-ano. Say the pronoun when it's ambiguous.","The VEDONO trigger list: Volontà (voglio che), Emozione (sono contenta che), Dubbio (dubito che), Opinione (penso che), Necessità (bisogna che), cOngiunzioni (benché, prima che).","The exception that saves you: 'SECONDO ME' takes the plain indicative — 'Secondo me ha ragione'. So does 'so che' and 'è vero che' (facts)."],
 examples:[{it:"Penso che il paziente abbia bisogno di riposo.",en:"I think the patient needs rest."},{it:"Secondo me hai ragione, ma non credo che sia così semplice.",en:"In my opinion you're right, but I don't think it's that simple."}],
 bridge:[{en:"'If I WERE you' — English keeps this mood in one fossil",it:"Se fossi in te — Italian uses that mood after every opinion verb"},{en:"'I suggest he BE on time' — another English fossil of the same mood",it:"Voglio che lui SIA puntuale"}]},
 mnemonic:"VEDONO un congiuntivo: Volontà, Emozione, Dubbio, Opinione, Necessità, cOngiunzioni — if the first verb 'sees' one of these + che, the second verb changes mood.",
 note:"penso che + congiuntivo (abbia/sia/faccia) · io=tu=lui, add the pronoun · SECONDO ME + indicativo · facts (so che) stay indicativo",
 drills:[
  {q:"Penso che Marco ___ ragione.",options:["abbia","ha","avere","avrà"],answer:0,why:"Opinion + che → mood change",err:"congiuntivo_quando"},
  {q:"Secondo me il medico ___ stanco.",options:["è","sia","fosse","sarebbe"],answer:0,why:"'Secondo me' = no che → plain indicative",err:"congiuntivo_quando"},
  {q:"Credo che tu ___ un bravo dottore.",options:["sia","sei","sarai","fossi"],answer:0,why:"credo che → sia",err:"congiuntivo_quando"},
  {q:"So che loro ___ in ritardo.",options:["sono","siano","fossero","sarebbero"],answer:0,why:"Knowing a fact → indicative",err:"congiuntivo_quando"},
  {q:"Mi sembra che voi ___ troppo. (lavorare)",options:["lavoriate","lavorate","lavorano","lavoriamo"],answer:0,why:"voi in this mood → -iate",err:"congiuntivo_forma"},
  {q:"Non credo che ___ vero.",options:["sia","è","sarà","sarebbe"],answer:0,why:"Doubt/opinion → sia",err:"congiuntivo_quando"},
  {q:"Bisogna che il paziente ___ a digiuno.",options:["rimanga","rimane","rimarrà","rimanere"],answer:0,why:"Necessity + che → mood change",err:"congiuntivo_quando"},
  {q:"È vero che l'italiano ___ difficile.",options:["è","sia","fosse","sarebbe"],answer:0,why:"'È vero che' states a fact → indicative",err:"congiuntivo_quando"},
  {q:"Spero che tu ___ bene. (stare)",options:["stia","stai","stessi","starai"],answer:0,why:"Hope = emotion → stia",err:"congiuntivo_forma"},
  {q:"Penso che (loro) ___ domani. (partire)",options:["partano","partono","partino","partiranno"],answer:0,why:"-ire verbs, loro → -ano in this mood",err:"congiuntivo_forma"}],
 speak:{prompt:"Give an opinion with 'penso che' and one with 'secondo me'.",model:"Penso che l'ospedale sia troppo pieno. Secondo me servono più infermieri."},
 newcards:[{it:"Penso che sia…",en:"I think it is… (mood-switched)",mn:"penso CHE flips the switch → sia",ex:"Penso che sia una buona idea."},{it:"Secondo me",en:"In my opinion (no mood switch!)",mn:"SECONDO ME is the exit door from the congiuntivo",ex:"Secondo me hai ragione."},{it:"Bisogna che",en:"It's necessary that (+ congiuntivo)",mn:"Bisogna = needs; needs see a congiuntivo",ex:"Bisogna che tu riposi."}]},

b1u2:{concept:{title:"Pronomi ninja — glielo, ce ne, and the little words that hide",
 bullets:["Direct object: lo/la/li/le (it/him/her/them). Indirect: mi/ti/gli/le/ci/vi/gli (to me… to them). They sit BEFORE the verb: 'Lo vedo', 'Gli parlo'.","Two pronouns together: the indirect one changes -i → -e and goes first: me lo, te lo, ce lo, ve lo. GLI + LO fuse into GLIELO (also for 'le' — to her — and 'loro').","With an infinitive they glue to the end: 'Devo dirglielo' or 'Glielo devo dire' — both fine.","CI = there (Ci vado = I go there). NE = of it/them (Ne prendo due). 'Non ce la faccio' = I can't manage. 'Ce n'è ancora?' = is there any left?"],
 examples:[{it:"Il referto? Glielo mando subito, dottoressa.",en:"The report? I'll send it to you (formal) right away, doctor."},{it:"Quanti pazienti ci sono? — Ce ne sono dodici.",en:"How many patients are there? — There are twelve (of them)."}],
 bridge:[{en:"'I'll send it to him' — English keeps two separate words",it:"Glielo mando — Italian welds them into one"},{en:"'I'll take two of them'",it:"Ne prendo due — NE is the 'of them' English drops"}]},
 mnemonic:"Indirect goes first and turns its -i into -e: ME lo, TE lo, CE lo. Only GLI refuses and marries: GLIELO.",
 note:"me lo / te lo / ce lo / ve lo · gli+lo = glielo (also for 'to her') · ci = there · ne = of it · non ce la faccio",
 drills:[
  {q:"Hai dato il referto al primario? — Sì, ___ ho dato stamattina.",options:["glielo","gli lo","lo gli","gliel'"],answer:0,why:"gli + lo → glielo",err:"pronomi"},
  {q:"Mi presti la penna? — Certo, ___ presto.",options:["te la","ti la","la ti","te lo"],answer:0,why:"ti → te before la",err:"pronomi"},
  {q:"Quante compresse prende? — ___ prendo due al giorno.",options:["Ne","Le","Ci","Li"],answer:0,why:"Of them → ne",err:"pronomi"},
  {q:"Vai in ospedale domani? — Sì, ___ vado alle otto.",options:["ci","ne","lo","vi"],answer:0,why:"There → ci",err:"pronomi"},
  {q:"Non ___ la faccio più, sono esausta.",options:["ce","ci","ne","me"],answer:0,why:"Fixed phrase: non ce la faccio",err:"pronomi"},
  {q:"Devo dire la verità a Maria. → Devo ___.",options:["dirgliela","dirlela","dirla a lei","dirle la"],answer:0,why:"le + la → gliela, glued to the infinitive",err:"pronomi"},
  {q:"C'è ancora caffè? — No, non ___ più.",options:["ce n'è","c'è ne","ne c'è","ce ne"],answer:0,why:"ci + ne + è → ce n'è",err:"pronomi"},
  {q:"Hai visto le analisi? — Sì, ___ ho viste.",options:["le","li","la","gli"],answer:0,why:"le analisi (fem. pl.) → le, and 'viste' agrees",err:"pronomi"},
  {q:"Ci mandate i risultati? — Sì, ___ mandiamo domani.",options:["ve li","vi li","ve le","ce li"],answer:0,why:"vi → ve before li",err:"pronomi"},
  {q:"Hai parlato ai pazienti? — Sì, ___ ho parlato.",options:["gli","li","le","loro"],answer:0,why:"To them (spoken Italian) → gli",err:"pronomi"}],
 speak:{prompt:"Say you'll send the report to the doctor and that there are three copies of it.",model:"Glielo mando subito. Ce ne sono tre copie."},
 newcards:[{it:"glielo",en:"it to him / to her / to them",mn:"GLI marries LO — glielo, one word",ex:"Glielo dico io."},{it:"non ce la faccio",en:"I can't manage / I can't take it",mn:"CE LA — the untranslatable 'it' of coping",ex:"Non ce la faccio più con questi turni."},{it:"ce n'è / ce ne sono",en:"there is some / there are some (of them)",mn:"ci + ne + è, all squashed",ex:"Ce ne sono ancora due."}]},

b1u3:{concept:{title:"In ospedale — departments, admission, the first anamnesi",
 bullets:["Where things are: il pronto soccorso (ER), il reparto (ward), la corsia (the ward corridor/bay), la sala operatoria, il laboratorio analisi, la radiologia, l'ambulatorio (outpatient clinic).","Admission words: il ricovero (admission), ricoverare (to admit), la dimissione / dimettere (discharge), la cartella clinica (chart), il referto (report), la terapia (treatment/meds).","The anamnesi skeleton in Lei form: 'Qual è il motivo del ricovero?' 'Ha altre malattie?' 'Prende farmaci?' 'È allergico a qualcosa?' 'Fuma? Beve?' 'In famiglia ci sono malattie…?'","Register: patients get LEI; the participle of 'ricoverare' behaves: 'È stato ricoverato ieri' (he was admitted yesterday)."],
 examples:[{it:"Il signor Rossi è stato ricoverato ieri in Medicina Interna per dolore toracico.",en:"Mr Rossi was admitted yesterday to Internal Medicine for chest pain."},{it:"Buongiorno, sono la studentessa del reparto. Posso farle qualche domanda sulla sua storia clinica?",en:"Good morning, I'm the student on the ward. May I ask you a few questions about your medical history?"}],
 bridge:[{en:"'He was admitted yesterday' — same passive shape",it:"È stato ricoverato ieri — essere + stato + participle"},{en:"'Do you take any medication?' — the formal 'you'",it:"Prende farmaci? — Lei form, third person"}]},
 mnemonic:"RICOVERO in, DIMISSIONE out — you get 'covered' when admitted and 'de-missioned' when sent home.",
 note:"pronto soccorso · reparto · ricovero/dimissione · cartella clinica · referto · anamnesi in Lei: Qual è il motivo? Prende farmaci? È allergico?",
 drills:[
  {q:"Il paziente è stato ___ ieri in Cardiologia.",options:["ricoverato","dimesso","riservato","recuperato"],answer:0,why:"ricoverare = to admit",err:"vocab"},
  {q:"«Il pronto soccorso» is…",options:["the emergency room","the ready help desk","the pharmacy","the ambulance"],answer:0,why:"pronto soccorso = ER",err:"vocab"},
  {q:"Signora, ___ farmaci? (formal)",options:["prende","prendi","prendete","prenda"],answer:0,why:"Lei form = third person",err:"registro"},
  {q:"«La cartella clinica» is…",options:["the patient's chart/record","the clinic's business card","the folder of X-rays","the prescription"],answer:0,why:"cartella = file/record",err:"vocab"},
  {q:"Il paziente sarà ___ domani, sta bene.",options:["dimesso","ricoverato","ammesso","rimesso"],answer:0,why:"dimettere = discharge",err:"vocab"},
  {q:"«È allergico ___ qualche farmaco?»",options:["a","di","per","con"],answer:0,why:"allergico A",err:"preposizioni"},
  {q:"Il referto ___ arrivato dal laboratorio.",options:["è","ha","sia","abbia"],answer:0,why:"arrivare → essere",err:"ausiliare"},
  {q:"Which is the outpatient clinic?",options:["l'ambulatorio","l'ambulanza","la corsia","la sala operatoria"],answer:0,why:"ambulatorio ≠ ambulanza (ambulance)",err:"vocab"},
  {q:"Qual è il ___ del ricovero?",options:["motivo","perché","ragionamento","causa di"],answer:0,why:"motivo del ricovero = reason for admission",err:"vocab"},
  {q:"«Ha altre malattie?» — the doctor asks about…",options:["other illnesses","other doctors","bad habits","other symptoms today"],answer:0,why:"malattie = illnesses",err:"vocab"}],
 speak:{prompt:"Introduce yourself to a patient as the ward student and ask the reason for admission.",model:"Buongiorno, sono lo studente del reparto. Qual è il motivo del ricovero?"},
 newcards:[{it:"il ricovero / ricoverare",en:"admission / to admit (to hospital)",mn:"Get 'covered' by the hospital",ex:"Il ricovero è durato tre giorni."},{it:"dimettere / la dimissione",en:"to discharge / discharge",mn:"De-mission: your mission at the hospital ends",ex:"Domani la dimettiamo."},{it:"il referto",en:"the (test/imaging) report",mn:"What the lab REFERs back",ex:"Il referto della TAC è pronto."}]},

b1u4:{concept:{title:"Se potessi… — the conditional and the polite hypothetical",
 bullets:["Conditional = future stem + -ei -esti -ebbe -emmo -este -ebbero: parlerei, sarei, avrei, vorrei, potrei, dovrei.","Politeness engine: 'Vorrei' (I'd like), 'Potrebbe…?' (could you…?), 'Dovresti' (you should), 'Mi piacerebbe' (I'd love to).","The hypothetical pair: SE + congiuntivo imperfetto, THEN condizionale. 'Se avessi tempo, verrei.' The congiuntivo imperfetto: avessi, fossi, potessi, facessi (-assi/-essi/-issi).","Trap: never 'se avrei'. The SE half never takes the conditional — it takes the -SSI form."],
 examples:[{it:"Se potessi, farei la specializzazione a Bologna.",en:"If I could, I'd do my specialty training in Bologna."},{it:"Dottore, potrebbe spiegarmi il referto? Vorrei capire meglio.",en:"Doctor, could you explain the report to me? I'd like to understand better."}],
 bridge:[{en:"'If I HAD time, I WOULD come' — same two-part shape",it:"Se AVESSI tempo, VERREI"},{en:"'Could you…?' for politeness",it:"Potrebbe…? — conditional does the softening"}]},
 mnemonic:"SE takes the -SSI (avessi, fossi), the result takes -EI/-EBBE (avrei, sarebbe). SE + SSI, never SE + -EI.",
 note:"condizionale: -ei -esti -ebbe -emmo -este -ebbero (vorrei, potrei, dovrei) · se + avessi/fossi → condizionale · never 'se avrei'",
 drills:[
  {q:"Se ___ tempo, verrei volentieri.",options:["avessi","avrei","avevo","abbia"],answer:0,why:"SE takes the -ssi form",err:"condizionale"},
  {q:"___ un'informazione, per favore. (I'd like)",options:["Vorrei","Voglio","Volevo","Vorrò"],answer:0,why:"Polite request → vorrei",err:"registro"},
  {q:"Se fossi in te, ___ dal medico.",options:["andrei","vado","andassi","andrò"],answer:0,why:"Result half → conditional",err:"condizionale"},
  {q:"___ ripetere, per favore? (could you, formal)",options:["Potrebbe","Potresti","Può","Poteva"],answer:0,why:"Lei + conditional = maximum politeness",err:"registro"},
  {q:"Noi ___ più tempo con i pazienti. (dovere)",options:["dovremmo","dovremo","dovessimo","doveremmo"],answer:0,why:"dovere → dovr-emmo (double m = conditional)",err:"coniugazione"},
  {q:"Se il paziente ___ meno, respirerebbe meglio. (fumare)",options:["fumasse","fumerebbe","fuma","fumi"],answer:0,why:"se + -asse",err:"condizionale"},
  {q:"Mi ___ molto lavorare all'estero. (piacere)",options:["piacerebbe","piacerà","piaceva","piaccia"],answer:0,why:"I'd love to → piacerebbe",err:"coniugazione"},
  {q:"Which is WRONG?",options:["Se avrei tempo, verrei.","Se avessi tempo, verrei.","Verrei, se avessi tempo.","Se potessi, verrei."],answer:0,why:"Never se + conditional",err:"condizionale"},
  {q:"Loro ___ subito, ma non hanno la macchina. (partire)",options:["partirebbero","partiranno","partissero","partirono"],answer:0,why:"They would leave → -irebbero",err:"coniugazione"},
  {q:"Se tu ___ più attento, faresti meno errori. (essere)",options:["fossi","saresti","eri","sia"],answer:0,why:"se + fossi",err:"condizionale"}],
 speak:{prompt:"Say what you would do if you had more time, and ask a doctor politely to repeat.",model:"Se avessi più tempo, studierei anche il francese. Dottore, potrebbe ripetere, per favore?"},
 newcards:[{it:"Se avessi… farei…",en:"If I had… I would do…",mn:"SE + SSI, result + EI",ex:"Se avessi soldi, farei un viaggio."},{it:"Potrebbe…?",en:"Could you…? (formal)",mn:"The politest three syllables in Italian",ex:"Potrebbe parlare più lentamente?"},{it:"Mi piacerebbe",en:"I would like / I'd love to",mn:"It WOULD please me",ex:"Mi piacerebbe lavorare in pediatria."}]},

b1u5:{concept:{title:"Raccontami — connectors, storytelling, and recognizing the passato remoto",
 bullets:["Story glue: prima (first), poi (then), dopo (after), mentre (while), all'improvviso (suddenly), alla fine (in the end), infatti (indeed), invece (instead/whereas), quindi (so), però (but).","A good story alternates: imperfetto for the scene (era tardi, pioveva), passato prossimo for the events (è entrato, ha detto).","Passato remoto = the literary/historical past: 'Dante nacque nel 1265', 'disse', 'fu', 'andò', 'fece'. You READ it (novels, history, Wikipedia) — in the North you almost never SAY it. Southern Italy uses it in speech.","Recognize the shapes: -ò / -è / -ì endings (parlò, credé, partì), and irregulars: fu (was), ebbe (had), fece (did), disse (said), venne (came), vide (saw)."],
 examples:[{it:"Era tardi, pioveva, e all'improvviso è entrato un paziente con il braccio rotto. Alla fine l'abbiamo ricoverato.",en:"It was late, it was raining, and suddenly a patient came in with a broken arm. In the end we admitted him."},{it:"Fleming scoprì la penicillina nel 1928.",en:"Fleming discovered penicillin in 1928. (passato remoto: you read this, you don't say it)"}],
 bridge:[{en:"'It was late and suddenly he walked in' — scene + event",it:"Era tardi e all'improvviso è entrato"},{en:"'Thus spake…' — English has an archaic past too; Italian's is the passato remoto",it:"Disse, fece, andò — read it, don't fear it"}]},
 mnemonic:"Remoto = REMOTE: it lives in books and in the South. Spot it by the accent at the end: parlÒ, partÌ.",
 note:"prima·poi·mentre·all'improvviso·alla fine · scene = imperfetto, events = passato prossimo · remoto (parlò, fu, fece, disse) = books & the South",
 drills:[
  {q:"«Dante ___ nel 1265.» (in a history book)",options:["nacque","è nato","nasceva","nascerà"],answer:0,why:"Historical narration → passato remoto",err:"tempo_passati"},
  {q:"«Fece» is the passato remoto of…",options:["fare","fingere","farcire","fermare"],answer:0,why:"fare → fece",err:"coniugazione"},
  {q:"Era tardi e all'improvviso ___ il telefono.",options:["ha squillato","squillava","squillò sempre","squilla"],answer:0,why:"Sudden event breaking the scene → passato prossimo",err:"tempo_passati"},
  {q:"«Prima ho fatto colazione, ___ sono uscita.»",options:["poi","mentre","invece","però"],answer:0,why:"Sequence → poi",err:"vocab"},
  {q:"«Fu» is the passato remoto of…",options:["essere","fare","avere","fuggire"],answer:0,why:"essere → fu",err:"coniugazione"},
  {q:"Pensavo di riposare, ___ mi hanno chiamata in reparto.",options:["invece","quindi","infatti","prima"],answer:0,why:"Contrast with expectation → invece",err:"vocab"},
  {q:"Which sentence is natural in SPOKEN Milanese Italian?",options:["Ieri ho visto Marco.","Ieri vidi Marco.","Ieri vedetti Marco.","Ieri vedevo Marco una volta."],answer:0,why:"Spoken North → passato prossimo",err:"registro"},
  {q:"«Disse» means…",options:["he/she said","he/she gave","he/she left","he/she saw"],answer:0,why:"dire → disse",err:"coniugazione"},
  {q:"Mentre ___ la cartella, il paziente ha iniziato a tossire.",options:["leggevo","ho letto","lessi","leggo"],answer:0,why:"mentre + ongoing scene → imperfetto",err:"tempo_passati"},
  {q:"Non ho studiato, ___ ho fallito l'esame.",options:["quindi","però","mentre","prima"],answer:0,why:"Consequence → quindi",err:"vocab"}],
 speak:{prompt:"Tell a short story: the scene (imperfetto), then what suddenly happened, then the ending.",model:"Era mezzanotte e il reparto era tranquillo. All'improvviso è arrivata un'ambulanza. Alla fine è andato tutto bene."},
 newcards:[{it:"all'improvviso",en:"suddenly",mn:"Un-foreseen (im-pro-visto) → suddenly",ex:"All'improvviso ha iniziato a piovere."},{it:"invece",en:"instead / whereas / but actually",mn:"IN VECE = in place of what you expected",ex:"Volevo dormire, invece ho lavorato."},{it:"fu / fece / disse",en:"was / did / said (passato remoto)",mn:"The book-past trio — read them, don't say them (in the North)",ex:"Fu un anno difficile, disse il primario."}]},

/* ===================== B2 ===================== */
b2u1:{concept:{title:"Congiuntivo II — the past moods and the conjunctions that demand them",
 bullets:["Congiuntivo imperfetto (-assi/-essi/-issi; fossi, avessi) after a PAST main verb: 'Pensavo che fosse stanco' (I thought he was tired).","Congiuntivo passato = abbia/sia + participle, for a completed action seen from the present: 'Penso che sia già partito' (I think he has already left).","Congiuntivo trapassato = avessi/fossi + participle: 'Pensavo che fosse già partito' (I thought he had already left).","Conjunctions that ALWAYS take the congiuntivo: benché/sebbene/nonostante (although), affinché/perché (so that), prima che (before), a meno che non (unless), purché (provided that), senza che."],
 examples:[{it:"Benché fosse esausto, il chirurgo ha finito l'intervento.",en:"Although he was exhausted, the surgeon finished the operation."},{it:"Ti spiego tutto affinché tu capisca il piano terapeutico.",en:"I'll explain everything so that you understand the treatment plan."}],
 bridge:[{en:"'I thought he WAS tired' — the past version of the opinion",it:"Pensavo che FOSSE stanco"},{en:"'Although it may be…' — English's fossil of 'although' + mood",it:"Benché sia… — Italian keeps it alive on every 'although'"}]},
 mnemonic:"Time-travel rule: main verb in the past → congiuntivo takes the -SSI form. BENCHÉ, AFFINCHÉ, PRIMA CHE, PURCHÉ: the -CHÉ gang always demands it.",
 note:"pensavo che + fosse/avesse (-ssi) · penso che sia partito (past) · pensavo che fosse partito (had) · benché/affinché/prima che/purché → congiuntivo",
 drills:[
  {q:"Pensavo che il medico ___ già arrivato.",options:["fosse","sia","era","fosse stato"],answer:0,why:"Past main verb → fosse (+ arrivato = had arrived)",err:"congiuntivo_forma"},
  {q:"Benché ___ tardi, il reparto era pieno.",options:["fosse","era","sia","sarebbe"],answer:0,why:"Benché + past context → fosse",err:"congiuntivo_quando"},
  {q:"Credo che loro ___ ieri. (partire, completed)",options:["siano partiti","sono partiti","fossero partiti","partano"],answer:0,why:"Present opinion about a completed past → sia + participle",err:"congiuntivo_forma"},
  {q:"Prima che il paziente ___, fategli l'ECG.",options:["esca","esce","uscisse","uscirà"],answer:0,why:"prima che → congiuntivo (present context)",err:"congiuntivo_quando"},
  {q:"Volevo che tu ___ con me. (venire)",options:["venissi","venga","vieni","verresti"],answer:0,why:"Past wish → -issi",err:"congiuntivo_forma"},
  {q:"Ti chiamo ___ tu sappia i risultati.",options:["affinché","perché lo","così","quando"],answer:0,why:"Purpose → affinché + congiuntivo",err:"congiuntivo_quando"},
  {q:"Non credevo che ___ così grave.",options:["fosse","sia","era","fosse stato grave"],answer:0,why:"Past doubt → fosse",err:"congiuntivo_forma"},
  {q:"Puoi uscire, ___ tu torni prima di mezzanotte.",options:["purché","benché","perché","sebbene"],answer:0,why:"Condition ('provided that') → purché",err:"vocab"},
  {q:"Sebbene ___ piovuto tutta la notte, la strada era asciutta.",options:["avesse","abbia","aveva","ha"],answer:0,why:"Although it had rained → avesse piovuto",err:"congiuntivo_forma"},
  {q:"A meno che non ___ febbre, può tornare a casa.",options:["abbia","ha","avesse","avrà"],answer:0,why:"a meno che (non) → congiuntivo",err:"congiuntivo_quando"}],
 speak:{prompt:"Say something you thought yesterday that turned out wrong, using 'pensavo che… fosse'.",model:"Pensavo che l'esame fosse facile, invece era difficilissimo."},
 newcards:[{it:"Pensavo che fosse…",en:"I thought it was…",mn:"Past thought → -SSI form",ex:"Pensavo che fosse una vena, era un'arteria."},{it:"benché / sebbene",en:"although",mn:"The -CHÉ gang: always congiuntivo",ex:"Benché sia stanca, continuo."},{it:"purché",en:"provided that / as long as",mn:"PUR-ché = 'as long as' — a condition with a mood",ex:"Va bene, purché tu me lo dica prima."}]},

b2u2:{concept:{title:"Ipotesi — three kinds of 'if', and the one that means regret",
 bullets:["Type 1 (real): SE + presente/futuro, result presente/futuro. 'Se piove, resto a casa.' 'Se studi, passerai.'","Type 2 (possible/unlikely): SE + congiuntivo imperfetto, result condizionale presente. 'Se avessi tempo, verrei.'","Type 3 (impossible, past regret): SE + congiuntivo trapassato (avessi/fossi + participle), result condizionale passato (avrei/sarei + participle). 'Se avessi saputo, sarei venuta.'","Mixed: past cause, present result: 'Se avessi studiato medicina in Italia, ora parlerei meglio.' Spoken Italian often uses the imperfetto for type 3: 'Se lo sapevo, venivo' — understand it, use it only informally."],
 examples:[{it:"Se avessi saputo del cambio turno, sarei arrivata prima.",en:"If I had known about the shift change, I would have arrived earlier."},{it:"Se il paziente fosse stato ricoverato prima, ora starebbe meglio.",en:"If the patient had been admitted earlier, he would be better now."}],
 bridge:[{en:"'If I had known, I would have come' — the regret shape",it:"Se avessi saputo, sarei venuta"},{en:"'If it rains, I'll stay home' — the plain one",it:"Se piove, resto a casa — no special mood at all"}]},
 mnemonic:"Regret needs TWO helpers: SE avessi/fossi + participle → avrei/sarei + participle. Doubled past = doubled regret.",
 note:"1: se + presente → presente/futuro · 2: se + avessi → avrei · 3: se + avessi saputo → avrei/sarei + participio · mixed: past se, present result",
 drills:[
  {q:"Se ___ studiato di più, avrei passato l'esame.",options:["avessi","avrei","avevo","abbia"],answer:0,why:"Type 3: se + avessi + participle",err:"condizionale"},
  {q:"Se lo avessi saputo, ___ prima.",options:["sarei venuta","venivo","sarei venuto sempre","verrei"],answer:0,why:"Past result → sarei + participle",err:"condizionale"},
  {q:"Se piove domani, ___ a casa.",options:["resto","resterei","restassi","sarei restato"],answer:0,why:"Real condition → plain present",err:"condizionale"},
  {q:"Se ___ in Italia da bambina, ora parlerei senza accento.",options:["fossi cresciuta","crescessi","sarei cresciuta","ero cresciuta"],answer:0,why:"Mixed: past se (fossi + participle), present result",err:"condizionale"},
  {q:"Se avessi tempo, ___ un corso di francese.",options:["farei","avrei fatto","facevo","faccio"],answer:0,why:"Type 2: present possibility → farei",err:"condizionale"},
  {q:"Se il chirurgo ___ più attento, non ci sarebbe stata la complicanza.",options:["fosse stato","era stato","sarebbe stato","sia stato"],answer:0,why:"Type 3 se-half → fosse stato",err:"condizionale"},
  {q:"Which is the informal spoken version of «Se lo avessi saputo, sarei venuto»?",options:["Se lo sapevo, venivo.","Se lo saprei, verrei.","Se lo so, vengo.","Se lo sapessi, venivo."],answer:0,why:"Colloquial double imperfetto",err:"registro"},
  {q:"Se non ___ l'antibiotico, l'infezione peggiorerà.",options:["prende","prendesse","prenderebbe","avesse preso"],answer:0,why:"Real future threat → type 1 present",err:"condizionale"},
  {q:"___ felice se tu venissi.",options:["Sarei","Sarò","Sono","Fossi"],answer:0,why:"Type 2 result → sarei",err:"condizionale"},
  {q:"Se avessimo chiamato prima, il paziente ___ ancora vivo.",options:["sarebbe","sarà","fosse","era"],answer:0,why:"Mixed: past cause, present result → sarebbe",err:"condizionale"}],
 speak:{prompt:"Express one regret with 'se avessi… avrei…'.",model:"Se avessi iniziato l'italiano prima, ora avrei meno problemi in reparto."},
 newcards:[{it:"Se avessi saputo…",en:"If I had known…",mn:"The regret opener — always followed by avrei/sarei",ex:"Se avessi saputo, non sarei venuta."},{it:"sarei venuto/a",en:"I would have come",mn:"Two helpers = past result",ex:"Sarei venuta, ma ero di turno."},{it:"magari!",en:"if only! / I wish!",mn:"MAGARI = the one-word regret",ex:"Hai vinto? — Magari!"}]},

b2u3:{concept:{title:"Il colloquio clinico — the full anamnesi, bad news, and Lei ↔ tu",
 bullets:["The full anamnesi map: motivo (chief complaint) → anamnesi patologica prossima (history of present illness: da quando, come, cosa peggiora/migliora) → remota (past illnesses, interventi) → farmacologica → familiare → fisiologica (fumo, alcol, allergie, alvo, diuresi).","Softening verbs for bad news: 'Purtroppo…', 'Devo dirle che…', 'I risultati non sono quelli che speravamo', 'Vorrei essere sincero con lei'. Pause. Ask: 'Vuole che le spieghi cosa significa?'","Register: you give LEI to every patient and colleague you don't know; older colleagues offer 'Diamoci del tu' — until then, Lei. Switching wrongly is a bigger error than a wrong verb.","Precision words: peggiorare/migliorare, insorgere (onset), acuto/cronico, il decorso (course), la prognosi, gli effetti collaterali."],
 examples:[{it:"Signora, purtroppo devo dirle che gli esami hanno confermato quello che temevamo. Vuole che le spieghi con calma cosa significa?",en:"Ma'am, unfortunately I have to tell you that the tests confirmed what we feared. Would you like me to calmly explain what it means?"},{it:"Il dolore è insorto tre giorni fa, peggiora con lo sforzo e migliora a riposo.",en:"The pain began three days ago, worsens with exertion and improves at rest."}],
 bridge:[{en:"'I'm afraid I have to tell you…' — the same soft landing",it:"Purtroppo devo dirle che…"},{en:"'Shall we drop the formalities?'",it:"Diamoci del tu — the Italian ritual of switching to 'tu'"}]},
 mnemonic:"PP-R-F-F-F: Prossima, Remota, Farmacologica, Familiare, Fisiologica — the anamnesi in five F-sounds.",
 note:"anamnesi: motivo → prossima → remota → farmacologica → familiare → fisiologica · bad news: Purtroppo… Vuole che le spieghi? · Lei until 'diamoci del tu'",
 drills:[
  {q:"«Anamnesi patologica remota» covers…",options:["past illnesses and operations","the present complaint","family diseases","medications"],answer:0,why:"remota = distant → past history",err:"vocab"},
  {q:"A patient says «Diamoci del tu». You should now…",options:["switch to the informal 'tu'","keep using Lei to be safe","use 'voi'","ask their age first"],answer:0,why:"They offered the switch — accept it",err:"registro"},
  {q:"«Purtroppo devo ___ che…» (formal, to a patient)",options:["dirle","dirti","dirvi","dirla"],answer:0,why:"To you (formal) → Le → dirle",err:"registro"},
  {q:"Il dolore ___ tre giorni fa. (onset)",options:["è insorto","ha insorto","insorgeva","insorgerà"],answer:0,why:"insorgere → essere + insorto",err:"ausiliare"},
  {q:"«Vuole che le ___ cosa significa?»",options:["spieghi","spiego","spiegherò","spiegasse"],answer:0,why:"Vuole che → congiuntivo",err:"congiuntivo_quando"},
  {q:"«Il decorso» is…",options:["the course (of an illness)","the discourse","the discharge","the corridor"],answer:0,why:"decorso = course/progression",err:"vocab"},
  {q:"Which question belongs to the «anamnesi fisiologica»?",options:["Fuma? Beve alcolici?","Quando è iniziato il dolore?","Ha fatto interventi chirurgici?","Prende farmaci?"],answer:0,why:"Habits & functions → fisiologica",err:"vocab"},
  {q:"Il dolore ___ con lo sforzo e ___ a riposo.",options:["peggiora / migliora","migliora / peggiora","insorge / decorre","cresce / muore"],answer:0,why:"Worsens with exertion, improves at rest",err:"vocab"},
  {q:"A colleague you've just met, 15 years older, in the ward. You say:",options:["«Buongiorno, dottoressa, posso farLe una domanda?»","«Ciao, posso farti una domanda?»","«Ehi, una domanda?»","«Buongiorno, ti posso chiedere?»"],answer:0,why:"Lei until offered otherwise",err:"registro"},
  {q:"«Gli effetti collaterali» are…",options:["side effects","lateral effects on the family","collateral damage","the effects on colleagues"],answer:0,why:"collaterale = side",err:"vocab"}],
 speak:{prompt:"Break bad news gently in two sentences, then offer to explain.",model:"Purtroppo i risultati non sono quelli che speravamo. Vuole che le spieghi con calma cosa significa?"},
 newcards:[{it:"anamnesi patologica prossima / remota",en:"history of present illness / past medical history",mn:"prossima = near (now), remota = far (past)",ex:"Nell'anamnesi remota: appendicectomia nel 2015."},{it:"Diamoci del tu",en:"Let's use 'tu' with each other",mn:"The ritual switch — wait for it",ex:"Dai, diamoci del tu, siamo colleghi."},{it:"insorgere (è insorto)",en:"to arise / onset (of a symptom)",mn:"in-SURGE — the symptom surges in",ex:"La febbre è insorta ieri sera."}]},

b2u4:{concept:{title:"Discutere & dibattere — arguing, conceding, interrupting politely",
 bullets:["Stating: 'A mio avviso…', 'Sono convinta che…' (+ congiuntivo), 'Non c'è dubbio che…' (+ indicativo — certainty!), 'Il punto è che…'.","Conceding then countering: 'È vero che… , però…', 'Capisco il tuo punto, tuttavia…', 'Ammetto che…, ma…', 'D'accordo, ciononostante…'.","Interrupting without a war: 'Scusa se ti interrompo…', 'Posso aggiungere una cosa?', 'Fammi finire' (informal), 'Mi lasci finire' (formal).","Structuring: 'In primo luogo… in secondo luogo… infine', 'Da un lato… dall'altro…', 'In conclusione…'. Hedging: 'Mi sa che…' (I have a feeling that — informal, indicativo)."],
 examples:[{it:"È vero che il sistema sanitario ha dei problemi, però resta uno dei migliori d'Europa.",en:"It's true the health system has problems, but it remains one of the best in Europe."},{it:"Scusa se ti interrompo, ma non sono d'accordo: a mio avviso il punto è un altro.",en:"Sorry to interrupt, but I disagree: in my view the point is a different one."}],
 bridge:[{en:"'It's true that…, but…' — concede then strike",it:"È vero che…, però…"},{en:"'On the one hand… on the other…'",it:"Da un lato… dall'altro…"}]},
 mnemonic:"Concede with È VERO CHE, counter with PERÒ. Certainty (non c'è dubbio) stays indicative; belief (sono convinta) goes congiuntivo.",
 note:"a mio avviso · sono convinta che + congiuntivo · non c'è dubbio che + indicativo · è vero che… però… · scusa se ti interrompo · da un lato… dall'altro",
 drills:[
  {q:"Non c'è dubbio che il vaccino ___ efficace.",options:["è","sia","fosse","sarebbe"],answer:0,why:"No doubt = certainty → indicative",err:"congiuntivo_quando"},
  {q:"Sono convinta che la riforma ___ necessaria.",options:["sia","è","sarà","fosse"],answer:0,why:"Conviction is still belief → congiuntivo",err:"congiuntivo_quando"},
  {q:"«Scusa se ti interrompo» is used to…",options:["interrupt politely","apologize for being late","end a conversation","agree"],answer:0,why:"Polite interruption",err:"vocab"},
  {q:"È vero che costa molto, ___ funziona.",options:["però","perché","quindi","affinché"],answer:0,why:"Concession then contrast → però",err:"vocab"},
  {q:"«A mio avviso» means…",options:["in my view","in my notice","in my advice","to my warning"],answer:0,why:"avviso here = opinion",err:"vocab"},
  {q:"Formal: «Mi ___ finire, per favore.»",options:["lasci","lascia","lasciate","lascio"],answer:0,why:"Lei imperative of lasciare → lasci",err:"registro"},
  {q:"«Mi sa che» is followed by…",options:["the indicative (mi sa che piove)","the congiuntivo (mi sa che piova)","the conditional","an infinitive"],answer:0,why:"Informal hedge, plain indicative",err:"congiuntivo_quando"},
  {q:"Da un lato è caro, ___ è l'unica soluzione.",options:["dall'altro","d'altra parte lo","dall'altro lato lo","invece l'"],answer:0,why:"da un lato… dall'altro",err:"vocab"},
  {q:"«Ciononostante» means…",options:["nevertheless","therefore","moreover","for instance"],answer:0,why:"ciò + nonostante = despite that",err:"vocab"},
  {q:"Ammetto che tu ___ ragione su questo punto.",options:["abbia","hai","avessi","avrai"],answer:0,why:"ammettere che → congiuntivo (concession)",err:"congiuntivo_quando"}],
 speak:{prompt:"Concede a point, then counter it; use 'a mio avviso'.",model:"È vero che lo studio in inglese è più facile, però a mio avviso senza l'italiano in reparto non si sopravvive."},
 newcards:[{it:"a mio avviso",en:"in my view",mn:"My 'notice' = my view",ex:"A mio avviso è la scelta giusta."},{it:"È vero che…, però…",en:"It's true that…, but…",mn:"Concede, then strike",ex:"È vero che è tardi, però finiamo."},{it:"Scusa se ti interrompo",en:"Sorry to interrupt",mn:"The polite knife",ex:"Scusa se ti interrompo, ma c'è un errore."}]},

b2u5:{concept:{title:"La forma passiva & il si impersonale — the academic register",
 bullets:["Passive = essere + participle (agrees!) + 'da' for the agent: 'Il paziente è stato visitato dal primario.' Also with 'venire' for actions (not states): 'Il farmaco viene somministrato ogni 8 ore.'","'Andare' + participle = must be: 'Il modulo va compilato' (the form must be filled in). Very common in instructions.","SI impersonale = 'one / people / you (general)': 'In Italia si mangia bene', 'Si dice che…'. With a plural noun the verb goes plural: 'Si vendono farmaci' (drugs are sold).","Academic/clinical Italian loves the impersonal and the passive: 'Si osserva un aumento…', 'È stato dimostrato che…', 'Si raccomanda di…'."],
 examples:[{it:"Il farmaco viene somministrato per via endovenosa ogni otto ore; la dose va ridotta nei pazienti anziani.",en:"The drug is administered intravenously every eight hours; the dose must be reduced in elderly patients."},{it:"Si è osservato un miglioramento nel 70% dei casi.",en:"An improvement was observed in 70% of cases."}],
 bridge:[{en:"'It was shown that…' — passive for academic distance",it:"È stato dimostrato che…"},{en:"'One doesn't do that here' / 'you don't do that here'",it:"Qui non si fa così — SI does the 'one/you' job"}]},
 mnemonic:"VIENE for actions, È for states, VA for must-be-done. And SI: the anonymous subject that makes anything sound official.",
 note:"essere/venire + participio + da (agent) · va + participio = must be · si + verb (plural noun → plural verb) · si osserva / è stato dimostrato",
 drills:[
  {q:"Il paziente ___ visitato dal cardiologo ieri.",options:["è stato","ha stato","è","viene stato"],answer:0,why:"Past passive → è stato + participle",err:"ausiliare"},
  {q:"Il modulo ___ compilato prima del ricovero. (must be)",options:["va","viene","è","sta"],answer:0,why:"andare + participle = must be",err:"vocab"},
  {q:"In Italia ___ molto caffè.",options:["si beve","si bevono","beve","è bevuto"],answer:0,why:"si + singular noun → singular verb",err:"concordanza"},
  {q:"In farmacia ___ anche i cosmetici.",options:["si vendono","si vende","vendono si","è venduto"],answer:0,why:"Plural noun → plural verb",err:"concordanza"},
  {q:"La terapia ___ modificata ___ specialista.",options:["è stata / dallo","ha stata / dal","è stato / dello","viene stata / dallo"],answer:0,why:"Feminine agreement + da + article",err:"concordanza"},
  {q:"«Si dice che» is followed by…",options:["the congiuntivo (si dice che sia…)","always the indicative","an infinitive","the conditional"],answer:0,why:"Hearsay = doubt → congiuntivo",err:"congiuntivo_quando"},
  {q:"Il farmaco ___ somministrato ogni otto ore. (routine action)",options:["viene","è stato","va","sta"],answer:0,why:"Ongoing action passive → venire",err:"vocab"},
  {q:"«Si raccomanda di…» means…",options:["It is recommended to…","He recommends himself to…","We beg to…","They recommend each other…"],answer:0,why:"Impersonal recommendation",err:"vocab"},
  {q:"«È stato dimostrato che il fumo ___ dannoso.»",options:["è","sia","fosse","sarebbe"],answer:0,why:"Demonstrated fact → indicative",err:"congiuntivo_quando"},
  {q:"Le analisi ___ ripetute domani. (must be)",options:["vanno","va","vengono","sono"],answer:0,why:"Plural + must be → vanno",err:"concordanza"}],
 speak:{prompt:"Give two instructions in the academic register: one with 'va + participio', one with 'si'.",model:"La dose va ridotta negli anziani. Si raccomanda di controllare la funzione renale."},
 newcards:[{it:"va + participio",en:"must be (done)",mn:"It 'goes' done → must be done",ex:"Il consenso va firmato prima."},{it:"si dice che",en:"people say that / it is said that",mn:"SI = the anonymous 'they'",ex:"Si dice che il nuovo primario sia severo."},{it:"per via endovenosa / orale",en:"intravenously / orally",mn:"per VIA = by route",ex:"Somministrare per via orale."}]},

/* ===================== C1 ===================== */
c1u1:{concept:{title:"Sfumature — precision, near-synonyms, and the false friends to purge",
 bullets:["Synonyms are not equal: sentire (hear/feel/smell) vs ascoltare (listen) · vedere vs guardare · sapere (facts, how-to) vs conoscere (people, places) · portare (bring/carry/wear) vs prendere.","Register twins: iniziare/cominciare (neutral) vs avviare (formal, machines/processes) · finire vs terminare/concludere · dire vs affermare/sostenere (claim).","False friends that bite doctors: attualmente = currently (NOT actually → in realtà) · eventualmente = if need be (NOT eventually → alla fine) · sensibile = sensitive (sensible → ragionevole) · educato = polite (educated → istruito) · pretendere = to demand (pretend → fingere) · fattoria = farm (factory → fabbrica) · morbido = soft (morbid → morboso).","Precision adverbs: piuttosto (rather), addirittura (even/actually — surprise), perlomeno (at least), ormai (by now — with a tinge of 'too late'), appunto (exactly/precisely)."],
 examples:[{it:"Attualmente il paziente è stabile; eventualmente ripeteremo la TAC.",en:"Currently the patient is stable; if necessary we'll repeat the CT. (two false friends, both harmless here)"},{it:"Non è sensibile, è ragionevole: conosce bene il reparto e sa cosa fare.",en:"He's not sensitive, he's sensible: he knows the ward well and knows what to do."}],
 bridge:[{en:"'I know Paris' vs 'I know that Paris is big' — English hides the split",it:"Conosco Parigi / So che Parigi è grande — Italian names it"},{en:"'Actually' means 'in reality' in English",it:"Attualmente means 'currently' — the false friend that changes a clinical note"}]},
 mnemonic:"ATTUALMENTE is about NOW (attuale = current). EVENTUALMENTE is about MAYBE (eventuale = possible). Neither is what English thinks.",
 note:"sapere = facts · conoscere = people/places · attualmente = now · eventualmente = if needed · sensibile = sensitive · pretendere = demand · addirittura = even",
 drills:[
  {q:"«Attualmente» means…",options:["currently","actually","eventually","in fact"],answer:0,why:"attuale = current",err:"vocab"},
  {q:"«___ Roma molto bene.» (I know the city)",options:["Conosco","So","Sento","Vedo"],answer:0,why:"Places → conoscere",err:"vocab"},
  {q:"«Eventualmente possiamo cambiare terapia» means…",options:["If need be, we can change treatment","Eventually we will change treatment","We will finally change treatment","We already changed treatment"],answer:0,why:"eventuale = possible",err:"vocab"},
  {q:"Il paziente è molto ___ al dolore. (sensitive)",options:["sensibile","sensato","ragionevole","sensitivo"],answer:0,why:"sensibile = sensitive",err:"vocab"},
  {q:"«Pretendere» means…",options:["to demand","to pretend","to intend","to attend"],answer:0,why:"pretendere = demand; pretend = fingere",err:"vocab"},
  {q:"Non ho ___ nulla: eri troppo lontano. (heard)",options:["sentito","ascoltato","udire","conosciuto"],answer:0,why:"Passive hearing → sentire",err:"vocab"},
  {q:"«È addirittura peggiorato» means…",options:["He has even gotten worse","He got straight worse","He addressed the worsening","He got a bit worse"],answer:0,why:"addirittura = even (surprise)",err:"vocab"},
  {q:"«Un ragazzo molto educato» is…",options:["a very polite boy","a very educated boy","a well-trained boy","a well-read boy"],answer:0,why:"educato = polite; educated = istruito",err:"vocab"},
  {q:"«___ è troppo tardi per operare.» (by now)",options:["Ormai","Attualmente","Perlomeno","Appunto"],answer:0,why:"ormai = by now / too late",err:"vocab"},
  {q:"Non ___ guidare, non ho la patente. (know how to)",options:["so","conosco","posso","sento"],answer:0,why:"Skill/know-how → sapere",err:"vocab"}],
 speak:{prompt:"Use 'attualmente' and 'eventualmente' correctly in one clinical sentence.",model:"Attualmente la paziente è stabile; eventualmente aggiungeremo un diuretico."},
 newcards:[{it:"attualmente",en:"currently (NOT 'actually')",mn:"ATTUALE = current; actually = in realtà",ex:"Attualmente lavoro in pronto soccorso."},{it:"eventualmente",en:"if need be (NOT 'eventually')",mn:"EVENTUALE = possible; eventually = alla fine",ex:"Eventualmente chiamami."},{it:"addirittura",en:"even / as much as (surprise)",mn:"Straight-up! — the surprise intensifier",ex:"Ha addirittura chiamato il primario."}]},

c1u2:{concept:{title:"Italiano accademico — presenting a case, writing formally",
 bullets:["Caso clinico skeleton: 'Paziente di 67 anni, di sesso maschile, giunto alla nostra osservazione per…' → anamnesi → 'All'esame obiettivo si rileva…' → 'Gli esami ematochimici evidenziano…' → 'Si pone diagnosi di…' → 'Si avvia terapia con…' → decorso → 'In conclusione…'.","Formal verbs: rilevare (find), evidenziare (show), riscontrare (detect), porre diagnosi, avviare/impostare terapia, sottoporre a (subject to), presentare (to present with), lamentare (to complain of).","Nominal style: 'la comparsa di febbre' rather than 'è comparsa la febbre'; 'in seguito a' (following), 'in assenza di', 'a fronte di' (in the face of), 'ai fini di' (for the purpose of).","Formal e-mail: 'Gentile Professoressa…, Le scrivo in merito a… / per chiederLe… Resto a disposizione per qualsiasi chiarimento. Cordiali saluti.' Never 'Ciao prof'."],
 examples:[{it:"Paziente di 54 anni giunta alla nostra osservazione per dispnea ingravescente da tre giorni. All'esame obiettivo si rilevano rantoli bibasali.",en:"54-year-old patient presenting to us with worsening dyspnoea for three days. On examination, bibasal crackles are found."},{it:"Gentile Professore, Le scrivo in merito alla tesi. Resto a disposizione per qualsiasi chiarimento. Cordiali saluti.",en:"Dear Professor, I'm writing to you regarding the thesis. I remain available for any clarification. Kind regards."}],
 bridge:[{en:"'A 54-year-old presenting with…' — the case-report voice",it:"Paziente di 54 anni giunta per…"},{en:"'I remain at your disposal' — the formal sign-off",it:"Resto a disposizione"}]},
 mnemonic:"Formal Italian turns verbs into nouns and hides the doctor: 'si rileva', 'si pone diagnosi', 'si avvia terapia' — nobody did it, it was done.",
 note:"giunto alla nostra osservazione per · all'esame obiettivo si rileva · si pone diagnosi di · si avvia terapia · Gentile… Le scrivo in merito a… Cordiali saluti",
 drills:[
  {q:"«Giunto alla nostra osservazione per…» means…",options:["presented to us with…","joined our observation for…","came to observe us for…","was observed by us during…"],answer:0,why:"Case-report opener",err:"registro"},
  {q:"All'esame obiettivo si ___ un soffio sistolico.",options:["rileva","vede","sente","fa"],answer:0,why:"Formal: rilevare",err:"registro"},
  {q:"Formal e-mail opener to a professor:",options:["Gentile Professoressa,","Ciao Prof,","Cara Prof,","Ehi Professoressa,"],answer:0,why:"Gentile + title",err:"registro"},
  {q:"Si ___ diagnosi di polmonite.",options:["pone","fa","dà","mette"],answer:0,why:"porre diagnosi",err:"registro"},
  {q:"«Le scrivo in merito ___ colloquio di ieri.»",options:["al","del","per il","sul"],answer:0,why:"in merito A",err:"preposizioni"},
  {q:"Il paziente ___ dolore epigastrico. (complains of)",options:["lamenta","si lamenta di","piange","reclama"],answer:0,why:"lamentare (transitive) in clinical notes",err:"registro"},
  {q:"«In seguito a» means…",options:["following / as a result of","in the next","in a row","after all"],answer:0,why:"in seguito a = following",err:"vocab"},
  {q:"Nominal style: «È comparsa la febbre» →",options:["la comparsa di febbre","il comparire febbre","la febbre comparsa","comparendo febbre"],answer:0,why:"Verb → noun: la comparsa di",err:"registro"},
  {q:"Formal sign-off:",options:["Cordiali saluti","Un bacio","A presto!","Ciao ciao"],answer:0,why:"Cordiali saluti / Distinti saluti",err:"registro"},
  {q:"«Sottoporre il paziente ___ intervento.»",options:["a","per","ad un lungo","con"],answer:0,why:"sottoporre A",err:"preposizioni"}],
 speak:{prompt:"Open a case presentation in one formal sentence.",model:"Paziente di settant'anni, di sesso maschile, giunto alla nostra osservazione per dolore toracico insorto da due ore."},
 newcards:[{it:"giunto/a alla nostra osservazione per",en:"presenting to us with",mn:"The first line of every caso clinico",ex:"Paziente giunta alla nostra osservazione per sincope."},{it:"si rileva / si riscontra",en:"is found / is detected",mn:"The hidden doctor: 'it is found'",ex:"Si riscontra anemia lieve."},{it:"Resto a disposizione",en:"I remain at your disposal",mn:"The polite last line",ex:"Resto a disposizione per qualsiasi chiarimento."}]},

c1u3:{concept:{title:"Modi di dire — the idioms natives actually use",
 bullets:["In bocca al lupo! (good luck) → reply CREPI! (may it die). Never 'grazie'.","Everyday gold: 'Non vedo l'ora' (can't wait) · 'Mi raccomando' (please, I'm counting on you) · 'Boh' (no idea) · 'Magari' (I wish / maybe) · 'Figurati' (don't mention it) · 'Ci sto' (I'm in) · 'Che ne so' (how should I know).","Body idioms: 'Costa un occhio della testa' (costs an arm and a leg) · 'In gamba' (capable, sharp) · 'Avere le mani in pasta' (to be involved) · 'Rompere le scatole' (to be a pain) · 'Non avere peli sulla lingua' (to be blunt).","Ward idioms: 'Essere di turno' (on duty) · 'Fare la notte' (do the night shift) · 'Tirare avanti' (get by) · 'Acqua in bocca!' (keep it secret) · 'Tocca a te' (it's your turn)."],
 examples:[{it:"Domani ho l'esame. — In bocca al lupo! — Crepi!",en:"I have my exam tomorrow. — Good luck! — (May the wolf die!)"},{it:"Mi raccomando, acqua in bocca sul nuovo primario. — Figurati.",en:"Please, not a word about the new chief. — Don't worry."}],
 bridge:[{en:"'Break a leg!' — English also wishes you harm for luck",it:"In bocca al lupo! — reply Crepi!"},{en:"'It costs an arm and a leg'",it:"Costa un occhio della testa — an eye from the head"}]},
 mnemonic:"CREPI, not grazie: thanking the wolf brings bad luck. And MI RACCOMANDO has no English — it's a hug and a warning at once.",
 note:"in bocca al lupo → crepi · non vedo l'ora · mi raccomando · boh · magari · figurati · in gamba · costa un occhio della testa · essere di turno",
 drills:[
  {q:"«In bocca al lupo!» — the only correct reply:",options:["Crepi!","Grazie!","Anche a te!","Speriamo!"],answer:0,why:"May the wolf die — never thank it",err:"vocab"},
  {q:"«Non vedo l'ora di iniziare» means…",options:["I can't wait to start","I can't see the time to start","I don't know when to start","I never start on time"],answer:0,why:"Idiom: can't wait",err:"vocab"},
  {q:"«Mi raccomando» is closest to…",options:["Please — I'm counting on you","I recommend myself","I apologise","I command you"],answer:0,why:"Untranslatable plea/warning",err:"vocab"},
  {q:"«Boh» means…",options:["No idea","Wow","Yes","Oh no"],answer:0,why:"The shrug in one syllable",err:"vocab"},
  {q:"«È un medico in gamba» — he is…",options:["capable, sharp","tired, on his feet","on leave","standing in for someone"],answer:0,why:"in gamba = capable",err:"vocab"},
  {q:"«Costa un occhio della testa» means…",options:["it costs a fortune","it's an eye operation","it's a headache","it's worth a look"],answer:0,why:"an eye from the head = a fortune",err:"vocab"},
  {q:"«Grazie mille!» — «___»",options:["Figurati!","Crepi!","Magari!","Boh!"],answer:0,why:"Figurati = don't mention it",err:"vocab"},
  {q:"«Stasera faccio la notte» means…",options:["I'm on the night shift tonight","I'm going out tonight","I'll sleep late tonight","I'm doing an all-nighter of study"],answer:0,why:"fare la notte = night shift",err:"vocab"},
  {q:"«Acqua in bocca!» means…",options:["Keep it secret!","Drink some water!","Shut up!","Speak clearly!"],answer:0,why:"Water in mouth = can't talk",err:"vocab"},
  {q:"«Tocca a te» means…",options:["It's your turn","Touch it yourself","It's up to you to touch","You're touched"],answer:0,why:"toccare a = to be someone's turn",err:"vocab"}],
 speak:{prompt:"Wish a colleague luck, then use 'mi raccomando' about something.",model:"In bocca al lupo per l'esame! Mi raccomando, dormi stanotte."},
 newcards:[{it:"Crepi!",en:"(reply to 'in bocca al lupo') — may it die!",mn:"Kill the wolf, never thank it",ex:"In bocca al lupo! — Crepi!"},{it:"mi raccomando",en:"please, I'm counting on you / mind you",mn:"A hug and a warning in two words",ex:"Mi raccomando, chiamami quando arrivi."},{it:"non vedo l'ora",en:"I can't wait",mn:"I don't see the hour — it can't come fast enough",ex:"Non vedo l'ora che finisca il turno."}]},

c1u4:{concept:{title:"Registri — sliding between slang, standard, and the perfect email",
 bullets:["Three gears: colloquiale (che figata, un casino, mi sa, boh) → standard (molto bello, un problema, penso) → formale (notevole, una criticità, ritengo). Know which gear the room is in.","Formal markers: Lei + 'Le/La', 'Egregio/Gentile', 'La ringrazio', 'Cordiali/Distinti saluti', verbs like 'ritenere', 'necessitare di', 'provvedere a', 'in riferimento a'. PEC-speak: 'con la presente', 'in allegato', 'si prega di', 'in fede'.","Colloquial engines: 'mi sa che' (I reckon), 'un sacco di' (loads of), 'roba' (stuff), 'tipo' (like), 'cioè' (I mean), 'vabbè' (fine, whatever), 'dai' (come on), 'figo/figata' (cool).","Regional flavours to recognize: Milan 'sciura' (lady), 'ghe pensi mi' (I'll handle it); Rome 'daje' (come on), 'ahó', 'mo'' (now); Naples 'jamme' (let's go), 'uagliò' (kid). Hear them, don't fake them."],
 examples:[{it:"Colloquiale: «Mi sa che oggi è un casino in reparto.» · Formale: «Ritengo che la giornata in reparto presenti alcune criticità.»",en:"Informal: 'I reckon today's a mess on the ward.' · Formal: 'I believe the day on the ward presents some critical issues.'"},{it:"Con la presente si richiede il rilascio della certificazione. In allegato la documentazione. In fede, …",en:"Hereby the release of the certificate is requested. Attached, the documentation. Faithfully, …"}],
 bridge:[{en:"'Loads of stuff' vs 'a considerable amount of material' — same gears exist in English",it:"un sacco di roba vs una notevole quantità di materiale"},{en:"'Hereby' — the legal-letter word",it:"Con la presente — PEC-speak"}]},
 mnemonic:"Casino → problema → criticità. Same thing, three gears. Shift up for the Ordine, shift down for the aperitivo.",
 note:"colloquiale (mi sa, un casino, tipo, vabbè) · standard · formale (ritengo, criticità, con la presente, in allegato, in fede) · daje = Rome, sciura = Milan",
 drills:[
  {q:"Formal equivalent of «un casino»:",options:["una criticità","un problemone","un casinò","una situazione tipo"],answer:0,why:"criticità = formal 'issue'",err:"registro"},
  {q:"«Con la presente si richiede…» belongs to…",options:["a PEC / official letter","a WhatsApp message","a bar conversation","a medical chart"],answer:0,why:"con la presente = hereby",err:"registro"},
  {q:"«Mi sa che ha ragione» — register:",options:["colloquial","formal","academic","legal"],answer:0,why:"mi sa che = I reckon",err:"registro"},
  {q:"Formal: «In ___ trova la documentazione richiesta.»",options:["allegato","attaccato","aggiunta","appendice"],answer:0,why:"in allegato = attached",err:"registro"},
  {q:"«Daje!» is typical of…",options:["Rome","Milan","Naples","Venice"],answer:0,why:"Roman 'come on'",err:"vocab"},
  {q:"«Ritengo che» is the formal version of…",options:["penso che","dico che","so che","voglio che"],answer:0,why:"ritenere = to hold the view",err:"registro"},
  {q:"«Vabbè» means…",options:["fine, whatever","very well done","go well","it goes"],answer:0,why:"va bene squashed with a shrug",err:"vocab"},
  {q:"A PEC ends with…",options:["In fede,","Baci,","A presto,","Ciao!"],answer:0,why:"in fede = faithfully",err:"registro"},
  {q:"Formal: «Si ___ di compilare il modulo.»",options:["prega","chiede a tutti","dice","vuole"],answer:0,why:"si prega di = please (formal)",err:"registro"},
  {q:"«Un sacco di pazienti» in the standard gear:",options:["molti pazienti","un sacco pieno di pazienti","tanti tipo pazienti","pazienti a bizzeffe"],answer:0,why:"un sacco di → molti",err:"registro"}],
 speak:{prompt:"Say the same complaint twice: once to a friend, once to the head of department.",model:"A un amico: «Oggi è stato un casino.» Al primario: «Oggi la giornata ha presentato alcune criticità.»"},
 newcards:[{it:"mi sa che",en:"I reckon / I have a feeling that",mn:"It 'knows to me' — the gut speaking",ex:"Mi sa che domani piove."},{it:"criticità",en:"issue / critical point (formal)",mn:"Formal Italian for 'casino'",ex:"Segnalo alcune criticità nel reparto."},{it:"con la presente / in allegato / in fede",en:"hereby / attached / faithfully",mn:"The PEC trinity",ex:"Con la presente si trasmette, in allegato, il referto. In fede."}]},

c1u5:{concept:{title:"Retorica — persuasion, humour, and hearing irony",
 bullets:["Persuasion frames: 'Non si tratta di X, ma di Y' (it's not about X, it's about Y) · 'Il fatto è che…' · 'Proprio per questo…' (precisely for that reason) · 'Non a caso' (not by chance) · rhetorical 'Come si può negare che…?'.","Irony markers you must HEAR: 'Bella roba!' (great, said of something bad) · 'Complimenti!' (sarcastic when tone drops) · 'Ma va?' (you don't say) · 'Figuriamoci!' (as if!) · 'Ci mancava solo questo' (that's all we needed).","Understatement & litotes: 'Non è male' (it's pretty good) · 'Non proprio' (not exactly = no) · 'Mica male' (not bad at all) · 'Mica' = the emphatic 'not' (Non è mica facile!).","Humour engines: exaggeration ('Sono morta' = I'm exhausted), diminutives/pejoratives (-ino, -etto, -accio, -one: un lavoretto, una giornataccia, un problemone), and 'magari' as a wistful joke."],
 examples:[{it:"Non si tratta di soldi, ma di rispetto. Proprio per questo ho scritto al primario. Non a caso, ha risposto subito.",en:"It's not about money, it's about respect. Precisely for that reason I wrote to the chief. Not by chance, he answered at once."},{it:"Un altro turno di notte? Bella roba. Ci mancava solo questo.",en:"Another night shift? Great (ironic). That's all we needed."}],
 bridge:[{en:"'Oh, wonderful' (deadpan) — English irony by tone",it:"Bella roba! — Italian irony by phrase + tone"},{en:"'Not bad at all' — understatement for praise",it:"Mica male!"}]},
 mnemonic:"MICA = the Italian 'not… at all' spice. Mica male = really good. Non è mica facile = it's really not easy.",
 note:"non si tratta di X ma di Y · proprio per questo · non a caso · irony: bella roba, ma va?, ci mancava solo questo · mica male = good · -accio/-one/-ino",
 drills:[
  {q:"«Bella roba!» after hearing bad news is…",options:["ironic — 'great, just great'","a sincere compliment","a question","a greeting"],answer:0,why:"Irony marker",err:"vocab"},
  {q:"«Mica male» means…",options:["pretty good","a little bad","not even","very bad"],answer:0,why:"Understatement = praise",err:"vocab"},
  {q:"«Non si tratta di fortuna, ___ di preparazione.»",options:["ma","però","invece","anzi"],answer:0,why:"non… ma… frame",err:"vocab"},
  {q:"«Ma va?» said flatly means…",options:["You don't say (I knew that)","Does it work?","Go away","Really?! (surprised)"],answer:0,why:"Sarcastic 'no way'",err:"vocab"},
  {q:"«Una giornataccia» is…",options:["a terrible day","a long day","a big day","a short day"],answer:0,why:"-accia = bad",err:"vocab"},
  {q:"«Ci mancava solo questo» means…",options:["That's all we needed (ironic)","We only missed this","Only this was missing (good)","We nearly missed it"],answer:0,why:"Ironic complaint",err:"vocab"},
  {q:"«Non è ___ facile!» (emphatic not)",options:["mica","molto","tanto","proprio"],answer:0,why:"mica = not at all",err:"vocab"},
  {q:"«Proprio per questo» means…",options:["precisely for that reason","properly for this","just for this one","for exactly this person"],answer:0,why:"proprio = precisely",err:"vocab"},
  {q:"«Un problemone» is…",options:["a huge problem","a small problem","a fake problem","a problem child"],answer:0,why:"-one = big",err:"vocab"},
  {q:"«Figuriamoci!» means…",options:["As if! / No way!","Let's imagine it","Don't mention it","Picture this"],answer:0,why:"Dismissive irony",err:"vocab"}],
 speak:{prompt:"React ironically to bad news, then make a real point with 'non si tratta di… ma di…'.",model:"Un altro modulo? Bella roba. Ma non si tratta di burocrazia, ma di sicurezza del paziente."},
 newcards:[{it:"mica",en:"not at all (emphatic 'not')",mn:"MICA = the spice on a negative",ex:"Non è mica colpa mia!"},{it:"bella roba!",en:"great… (ironic)",mn:"'Nice stuff' said through gritted teeth",ex:"Sciopero dei treni? Bella roba."},{it:"non si tratta di… ma di…",en:"it's not about… it's about…",mn:"The reframe that wins arguments",ex:"Non si tratta di tempo, ma di priorità."}]},

/* ===================== C2 ===================== */
c2u1:{concept:{title:"Cultura viva — the references every Italian assumes you get",
 bullets:["TV & music: Sanremo (the February song festival everyone pretends not to watch), 'Un medico in famiglia' and 'DOC – Nelle tue mani' (the doctor shows), Fiorello, Benigni, Checco Zalone, Måneskin.","Calcio: la Serie A, il derby (Milan–Inter, Roma–Lazio), gli Azzurri (national team), 'il catenaccio' (defensive play — also used for stubborn bureaucracy), 'la Juve' and the Juventus jokes.","Politics you'll hear at the bar: 'il Palazzo' (the establishment), 'la Casta', 'il Quirinale' (the President), 'Montecitorio' (the Chamber), 'la Regione' (health is regional!), 'il concorso' (public competition for jobs).","Everyday rituals: 'l'aperitivo' (7 pm, Milan invented it), 'la pennichella' (siesta), 'il Ferragosto' (15 August — the country closes), 'la Befana' (6 January), 'lo spritz', 'la merenda', 'il rito del caffè al banco'."],
 examples:[{it:"Stasera c'è il derby, in reparto non risponde nessuno. — Ma va? Sanremo è finito da un mese.",en:"Tonight is the derby, nobody on the ward answers. — You don't say? Sanremo ended a month ago. (two references in one exchange)"},{it:"La sanità è regionale: il concorso lo bandisce la Regione, non Roma.",en:"Healthcare is regional: the job competition is announced by the Region, not Rome."}],
 bridge:[{en:"'The Super Bowl' — a national ritual disguised as sport",it:"Sanremo — a national ritual disguised as a song contest"},{en:"'Westminster' as shorthand for government",it:"Il Palazzo / il Quirinale / Montecitorio"}]},
 mnemonic:"Three things unite Italians: il caffè al banco, il derby, and complaining about Sanremo while watching it.",
 note:"Sanremo · DOC · derby · gli Azzurri · il Palazzo · la Regione runs health · concorso · aperitivo · Ferragosto · Befana",
 drills:[
  {q:"«Sanremo» is…",options:["the February song festival","a football stadium","a ministry","a saint's day"],answer:0,why:"The festival della canzone italiana",err:"vocab"},
  {q:"«Gli Azzurri» are…",options:["the national football team","the police","the Blue Party","hospital orderlies"],answer:0,why:"Blue shirts",err:"vocab"},
  {q:"Who announces most hospital job competitions in Italy?",options:["the Region","the Ministry in Rome","the Ordine","the EU"],answer:0,why:"Health is regional",err:"vocab"},
  {q:"«Ferragosto» is…",options:["15 August — the country stops","the first day of school","a food festival","the ferry to Sardinia"],answer:0,why:"Feriae Augusti",err:"vocab"},
  {q:"«Il Quirinale» stands for…",options:["the President of the Republic","the Senate","the Prime Minister","the Vatican"],answer:0,why:"The President's palace",err:"vocab"},
  {q:"«Il derby» in Milan is…",options:["Milan vs Inter","Milan vs Juventus","Inter vs Juventus","Milan vs Roma"],answer:0,why:"Same city, two clubs",err:"vocab"},
  {q:"«DOC – Nelle tue mani» is…",options:["a hospital TV drama","a wine label","a medical degree","a documentary channel"],answer:0,why:"The Italian doctor show",err:"vocab"},
  {q:"«La Befana» comes on…",options:["6 January","25 December","1 November","31 October"],answer:0,why:"Epiphany",err:"vocab"},
  {q:"«Il catenaccio», outside football, describes…",options:["stubborn, defensive obstruction","a chain of command","a key ring","a lock-in"],answer:0,why:"Defensive play → obstruction",err:"vocab"},
  {q:"«L'aperitivo» is…",options:["the pre-dinner drink ritual (~7 pm)","an appetizer at lunch","the morning coffee","a digestif"],answer:0,why:"Milan's gift to the world",err:"vocab"}],
 speak:{prompt:"Make small talk using two cultural references (calcio and a TV show).",model:"Hai visto il derby ieri? Io no, ero di turno — mi sono guardata una puntata di DOC."},
 newcards:[{it:"il concorso",en:"public competition for a job/place (incl. SSM)",mn:"The gate to every public job in Italy",ex:"Ho vinto il concorso per la specializzazione."},{it:"la Regione",en:"the Region (runs healthcare)",mn:"Health is regional — the Region pays and hires",ex:"La Regione ha bandito il concorso."},{it:"Ferragosto",en:"15 August (national shutdown)",mn:"August holiday — nobody answers",ex:"A Ferragosto l'ambulatorio è chiuso."}]},

c2u2:{concept:{title:"Dialetti & accenti — decode Milan, Rome and Naples",
 bullets:["Milan/North: closed vowels, 'e' for 'è', dropped final vowels ('andà' for andare in dialect), 'sciura', 'ghe', 'piuttosto che' misused to mean 'or'. Terms: 'la Madunina', 'bauscia' (show-off), 'pirla' (idiot).","Rome: doubled consonants in the middle ('a ccasa'), 'mo'' (now), 'daje', 'aó', 'annamo' (andiamo), 'nun' (non), 'ce sta' (c'è), 'famo' (facciamo), 'che te devo dì'. Warm, loud, ironic.","Naples/South: 'jamme', 'uagliò', 'guagliona', final vowels swallowed to a schwa ('Napul'), 'tengo' for 'ho' (I have), 'stare' for 'essere', passato remoto in speech ('vidi', 'feci' said daily).","Survival strategy: you don't SPEAK dialect — you RECOGNIZE it, smile, and answer in standard Italian. Patients will switch for you if you say 'Scusi, non ho capito bene, può ripetere in italiano?' without shame."],
 examples:[{it:"Roma: «Aó, che te devo dì, mo' ce sta 'na fila che nun finisce.» → Standard: «Cosa devo dirti, adesso c'è una fila che non finisce.»",en:"Rome: 'Hey, what can I tell you, right now there's a queue that never ends.'"},{it:"Napoli: «Tengo 'nu dolore ccà.» → Standard: «Ho un dolore qui.»",en:"Naples: 'I have a pain here.' — tengo = ho in the South"}],
 bridge:[{en:"'Gonna / wanna / y'all' — English also melts in the mouth",it:"annamo, famo, ce sta — Rome melts standard Italian the same way"},{en:"'I've got' vs 'I have' — a regional preference",it:"tengo vs ho — the South 'holds' instead of 'has'"}]},
 mnemonic:"Rome DOUBLES (a ccasa), Naples SWALLOWS (Napul'), Milan CLOSES (the vowels). Listen for the vowels first.",
 note:"Milan: sciura, pirla, bauscia · Rome: daje, mo', aó, annamo, nun, ce sta · Naples: jamme, uagliò, tengo = ho · recognize, don't imitate",
 drills:[
  {q:"Roman «mo'» means…",options:["now","more","but","me"],answer:0,why:"mo' = adesso",err:"vocab"},
  {q:"Neapolitan «tengo 'nu dolore» in standard Italian is…",options:["ho un dolore","tengo un dolore","sono un dolore","tiro un dolore"],answer:0,why:"tenere = avere in the South",err:"vocab"},
  {q:"«Sciura» is Milanese for…",options:["a (well-off) lady","a nurse","a nun","a cleaner"],answer:0,why:"la signora, Milan-style",err:"vocab"},
  {q:"«Daje» is used in…",options:["Rome","Milan","Naples","Turin"],answer:0,why:"Roman 'come on'",err:"vocab"},
  {q:"Roman «nun ce sta» =",options:["non c'è","non ci sta bene","non ce l'ha","non si sa"],answer:0,why:"nun = non, ce sta = c'è",err:"vocab"},
  {q:"«Jamme!» (Naples) means…",options:["Let's go!","Eat!","Stop!","Look!"],answer:0,why:"andiamo",err:"vocab"},
  {q:"A Neapolitan patient says «Ieri vidi il dottore». The tense is…",options:["passato remoto, used in daily speech in the South","a mistake for 'vedevo'","future","imperfetto"],answer:0,why:"Southern speech keeps the remoto",err:"tempo_passati"},
  {q:"«Pirla» (Milan) is…",options:["idiot (mild insult)","friend","boss","a pill"],answer:0,why:"Milanese for fool",err:"vocab"},
  {q:"Best reaction when you don't understand a dialect speaker:",options:["«Scusi, non ho capito bene, può ripetere in italiano?»","Nod and guess","Answer in the same dialect","Ask a colleague to translate every time"],answer:0,why:"Ask without shame; they'll switch",err:"registro"},
  {q:"Roman «famo» =",options:["facciamo","fame","famiglia","fumo"],answer:0,why:"Roman clipping of facciamo",err:"vocab"}],
 speak:{prompt:"Translate a Roman line into standard Italian out loud.",model:"«Aó, mo' ce sta 'na fila» → «Adesso c'è una fila.»"},
 newcards:[{it:"tengo (Sud) = ho",en:"I have (Southern usage)",mn:"The South HOLDS what the North HAS",ex:"Tengo famiglia."},{it:"daje / mo'",en:"come on / now (Rome)",mn:"The two Roman syllables you'll hear hourly",ex:"Daje, mo' annamo."},{it:"pirla / bauscia",en:"idiot / show-off (Milan)",mn:"Milan's two favourite insults",ex:"Non fare il pirla."}]},

c2u3:{concept:{title:"Il giro visite perfetto — leading a ward round in Italian",
 bullets:["Structure the presentation SBAR-style: Situazione (chi, perché ricoverato, giornata di degenza), Background (anamnesi essenziale), Assessment ('a mio parere il quadro è compatibile con…'), Raccomandazione ('propongo di…').","Round verbs: presentare il paziente, aggiornare la terapia, richiedere/prescrivere esami, valutare, monitorare, consultare (chiedere una consulenza), dimettere, programmare il follow-up.","Time language: 'in seconda giornata post-operatoria', 'nelle ultime 24 ore', 'da stanotte', 'a partire da domani', 'al momento', 'in attesa di' (pending).","Leading tone: decisive but consultative. 'Direi di…', 'Propongo…', 'Che ne dite se…?', 'Restiamo in attesa della consulenza cardiologica'. Pimping answers: 'Non lo so, ma lo verifico subito' beats a bluff."],
 examples:[{it:"Letto 4: signora Bianchi, 72 anni, in terza giornata per polmonite. Apiretica da stanotte, PCR in calo. Direi di passare alla terapia orale e programmare la dimissione per venerdì.",en:"Bed 4: Mrs Bianchi, 72, day three for pneumonia. Afebrile since last night, CRP falling. I'd suggest switching to oral therapy and planning discharge for Friday."},{it:"Che ne dite se chiediamo una consulenza nefrologica prima di aumentare il diuretico?",en:"What if we ask for a nephrology consult before increasing the diuretic?"}],
 bridge:[{en:"'Bed 4, day three, afebrile overnight' — round shorthand",it:"Letto 4, terza giornata, apiretica da stanotte"},{en:"'I'd suggest…' — soft leadership",it:"Direi di… / Propongo di…"}]},
 mnemonic:"S-B-A-R in Italian: Situazione, Background, Assessment (a mio parere), Raccomandazione (propongo di). Say it in under a minute.",
 note:"letto · giornata di degenza · apiretico · in calo/in aumento · direi di · propongo di · che ne dite se · in attesa di consulenza · programmare la dimissione",
 drills:[
  {q:"«In seconda giornata post-operatoria» means…",options:["on post-op day 2","in the second operating theatre","two days before surgery","during the second operation"],answer:0,why:"giornata = hospital day",err:"vocab"},
  {q:"«Apiretica da stanotte» means…",options:["afebrile since last night","feverish since last night","asleep since last night","in pain since last night"],answer:0,why:"a-piretico = without fever",err:"vocab"},
  {q:"The soft way to propose a plan on rounds:",options:["Direi di ridurre il diuretico.","Riduci il diuretico!","Il diuretico va bene così.","Non so cosa fare col diuretico."],answer:0,why:"Direi di = I'd suggest",err:"registro"},
  {q:"«Chiedere una consulenza» means…",options:["to request a specialist consult","to ask for advice from a friend","to consult the chart","to book a private visit"],answer:0,why:"consulenza = consult",err:"vocab"},
  {q:"«PCR in ___» (falling)",options:["calo","caduta","discesa libera","basso"],answer:0,why:"in calo = falling",err:"vocab"},
  {q:"«Che ne dite ___ passiamo alla terapia orale?»",options:["se","che","di","quando"],answer:0,why:"che ne dite se…",err:"preposizioni"},
  {q:"Asked a pimping question you can't answer, the best reply is…",options:["«Non lo so, ma lo verifico subito.»","a confident guess","silence","«Non è il mio paziente.»"],answer:0,why:"Honesty + action",err:"registro"},
  {q:"«Programmare la dimissione» =",options:["to plan the discharge","to program the admission","to schedule the operation","to cancel the discharge"],answer:0,why:"dimissione = discharge",err:"vocab"},
  {q:"«Restiamo in attesa ___ consulenza cardiologica.»",options:["della","per la","alla","con la"],answer:0,why:"in attesa DI",err:"preposizioni"},
  {q:"«Nelle ultime 24 ore» means…",options:["in the last 24 hours","in the next 24 hours","within 24 hours","for 24 hours"],answer:0,why:"ultime = last",err:"vocab"}],
 speak:{prompt:"Present a patient in four SBAR sentences, ending with a proposal.",model:"Letto 6, signor Conti, 65 anni, seconda giornata per scompenso cardiaco. Diuresi in aumento, dispnea in miglioramento. A mio parere risponde bene. Propongo di ridurre il diuretico da domani."},
 newcards:[{it:"in terza giornata",en:"on day three (of admission / post-op)",mn:"GIORNATA = the hospital's counting unit",ex:"Paziente in terza giornata post-operatoria."},{it:"Direi di… / Propongo di…",en:"I'd suggest… / I propose…",mn:"Lead softly: 'I'd say we…'",ex:"Direi di ripetere gli elettroliti."},{it:"in attesa di",en:"pending / awaiting",mn:"in WAIT of",ex:"In attesa di consulenza chirurgica."}]},

c2u4:{concept:{title:"Gioco di parole — double meanings and making natives laugh",
 bullets:["Homographs by stress: pèsca (peach) / pésca (fishing) · àncora (anchor) / ancóra (still) · prìncipi (princes) / princìpi (principles) · sùbito (immediately) / subìto (suffered).","Double meanings natives play with: 'medico' (doctor / I medicate), 'tempo' (time / weather / tense), 'piano' (slowly / floor / plan / piano), 'volo' (flight / I fly), 'sale' (salt / he goes up).","Comedy shapes: the fake proverb ('Chi dorme non piglia pesci… ma riposa'), the diminutive on something huge ('un problemino da 10.000 euro'), the deadpan 'magari', the stacked 'ma' ('ma dai, ma va, ma no').","Ward humour: 'il paziente è collaborante… quando dorme', 'siamo in tre: io, il caffè e la cartella', 'il primario ha detto di sì — ho sentito male'. Self-deprecation lands; sarcasm at patients never."],
 examples:[{it:"«Come va?» — «Piano, come l'ascensore del reparto.»",en:"'How's it going?' — 'Slowly, like the ward lift.' (piano = slowly AND floor)"},{it:"Ho preso una pèsca e sono andato a pésca. Ancóra? — No, l'àncora l'ho lasciata a casa.",en:"I took a peach and went fishing. Again? — No, I left the anchor at home. (stress puns)"}],
 bridge:[{en:"'Time flies like an arrow; fruit flies like a banana'",it:"Il tempo vola… e il volo è in ritardo — same double-meaning engine"},{en:"'Slightly' meaning 'hugely' — British understatement",it:"un problemino — the diminutive on a monster"}]},
 mnemonic:"Stress is a weapon: pèsca/pésca, àncora/ancóra, sùbito/subìto. Move the accent, change the joke.",
 note:"pèsca/pésca · àncora/ancóra · sùbito/subìto · piano = slowly/floor/plan · fake proverbs · diminutive on a monster (problemino) · self-deprecation yes, sarcasm at patients never",
 drills:[
  {q:"«Sùbito» vs «subìto»:",options:["immediately vs suffered","suffered vs immediately","both mean suddenly","both mean at once"],answer:0,why:"Stress changes the word",err:"ortografia"},
  {q:"«Piano» in «Vai piano!» means…",options:["slowly","floor","piano (instrument)","plan"],answer:0,why:"piano = slowly here",err:"vocab"},
  {q:"«Àncora» vs «ancóra»:",options:["anchor vs still/again","still vs anchor","both mean anchor","both mean again"],answer:0,why:"Stress splits them",err:"ortografia"},
  {q:"«Un problemino da 10.000 euro» is funny because…",options:["the diminutive shrinks something huge","10.000 is a small number","problemino means solution","it rhymes"],answer:0,why:"Understatement by diminutive",err:"vocab"},
  {q:"«Il tempo» can mean…",options:["time, weather, or tense","only time","only weather","only a musical tempo"],answer:0,why:"Triple meaning",err:"vocab"},
  {q:"«Sale» can be…",options:["salt / he goes up","only salt","only sale (discount)","dirty"],answer:0,why:"noun & verb clash",err:"vocab"},
  {q:"Which humour is safe on the ward?",options:["self-deprecation","sarcasm at a patient","jokes about a patient's dialect","mocking a colleague's accent"],answer:0,why:"Punch yourself, never the patient",err:"registro"},
  {q:"«Pèsca» (open è) is…",options:["peach","fishing","he fishes","fish"],answer:0,why:"pèsca = peach, pésca = fishing",err:"ortografia"},
  {q:"«Chi dorme non piglia pesci» means…",options:["the early bird catches the worm","sleep helps you fish","fish sleep too","don't nap after lunch"],answer:0,why:"Who sleeps catches no fish",err:"vocab"},
  {q:"«Prìncipi» vs «princìpi»:",options:["princes vs principles","principles vs princes","both = principles","both = princes"],answer:0,why:"Stress again",err:"ortografia"}],
 speak:{prompt:"Make a native laugh with one pun on 'piano' or 'tempo'.",model:"Il primario ha un piano per il reparto: il terzo piano, dove non lo trova nessuno."},
 newcards:[{it:"piano",en:"slowly / floor / plan / piano",mn:"One word, four jobs — the punster's dream",ex:"Vai piano, siamo al terzo piano."},{it:"sùbito / subìto",en:"immediately / suffered",mn:"Move the stress, change the story",ex:"Vengo sùbito! — Ho subìto un'ingiustizia."},{it:"un problemino",en:"a 'little' problem (often huge)",mn:"The diminutive that lies",ex:"C'è un problemino: manca il chirurgo."}]}
};

